# FR14 SERVED CHECKPOINT -- the single point of truth for the serve line.
# Deliberately NOT caller-overridable and deliberately NOT named FR13_*/LUMO_*/
# VLLM_* (those prefixes are auto-forwarded into the container by the env
# sweeper below, and this pair is host-side plumbing, not engine config).
# fr13_fixed32_contract.py pins the resulting PID1 argv element-by-element
# (MODEL_ROOT / MODEL_SERVED_NAME), so a divergence here fails closed at
# attestation rather than serving the wrong weights quietly.
SERVED_MODEL_PATH=/models/qwen3.8-27b-nvfp4-radixark
SERVED_MODEL_NAME=qwen3.8-27b-nvfp4-radixark
readonly SERVED_MODEL_PATH SERVED_MODEL_NAME
# FR14 ARM B: the NVFP4 lm_head is the arm. 1.83 of the 2.77 GB this arm's
# floor drops is the head alone (2.543 GB BF16 -> 0.715 GB NVFP4, 6.695 ms), so
# a boot that quietly fell back to an unquantized head would measure a wall
# against a floor 6.7 ms of which is fiction. The loader patch below is
# therefore mandatory and fail-closed, not optional.
#
# This is an FR14_* name on purpose: the env sweeper forwards ^(FR[0-9]+_|LUMO_|
# VLLM_) into the container, which is where the patcher reads it. It is read at
# PATCH time and baked into the emitted source, so the EngineCore worker's
# curated environment cannot silently disarm it.
export FR14_REQUIRE_NVFP4_LMHEAD=${FR14_REQUIRE_NVFP4_LMHEAD:-1}
[[ "$FR14_REQUIRE_NVFP4_LMHEAD" == "0" || "$FR14_REQUIRE_NVFP4_LMHEAD" == "1" ]] \
  || { echo "FR14_REQUIRE_NVFP4_LMHEAD must be exactly 0 or 1" >&2; exit 2; }
[[ -d "$SERVED_MODEL_PATH" && ! -L "$SERVED_MODEL_PATH" ]] \
  || { echo "served checkpoint directory is missing or symlinked: $SERVED_MODEL_PATH" >&2; exit 2; }
CONTAINER=${CONTAINER:-fr13-forked-fa2-tree}
PORT=${PORT:-9950}
_FR13_GPU_UTIL_EXPLICIT=${GPU_UTIL+x}
GPU_UTIL=${GPU_UTIL:-0.88}
# DURABLE OOM GUARD (2026-06-24): ALWAYS cap the container cgroup so the host keeps
# ~12GiB headroom -> Claude/watchdog/tmux can NEVER be the kernel OOM victim (GB10
# unified mem; the killer takes a -1000 proc only when nothing else can be freed).
# If a caller sets GPU_UTIL too high for this cap, the CONTAINER cgroup-OOMs at boot
# (relaunchable + LOUD), never the host. Diagnostics should also run ENFORCE_EAGER=1
# (the cuda-graph CAPTURE spike is the real trigger; eager stays flat). Default-ON so
# no caller can forget it (the repeat OOMs were callers that didn't set it).
_FR13_DOCKER_MEM_CAP_EXPLICIT=${DOCKER_MEM_CAP+x}
DOCKER_MEM_CAP=${DOCKER_MEM_CAP:-105g}
# UNIFIED-MEM OOM lesson (2026-06-24, dmesg-confirmed): the --memory cap does NOT
# constrain GPU/unified allocation (NVRM bypasses the cgroup), and a GPU OOM makes
# the kernel nuke the whole systemd --user session (sd-pam/systemd at +100) -> the
# login session tears down via SIGTERM, which oom_score_adj CANNOT prevent (claude
# was never a direct victim yet died with the session). So: (1) expandable_segments
# curbs eager caching-allocator fragmentation growth across varying prefill lengths;
# (2) a detached gpu_oom_guard (spawned below, post-boot) docker-kills THIS container
# if unified-avail nears the wall -> relaunchable+loud instead of a session kill.
PYTORCH_CUDA_ALLOC_CONF=${PYTORCH_CUDA_ALLOC_CONF:-expandable_segments:True}
GPU_OOM_GUARD=${GPU_OOM_GUARD:-1}
MAX_MODEL_LEN=${MAX_MODEL_LEN:-131072}
# FR14 ARM B: the ordered-GDN gates are DRAFT-VOCABULARY-PROFILE-AWARE.
# Ported from scripts/fr13_launch_forked_fa2_tree_server.sh (the reference
# implementation) because arm B's profile chain runs on the PROMOTED K0 config
# through exactly these leg3 paths. Before this port they carried the pre-train
# `K != 65536 || ROOT != 1` clause and passed no --draft-vocab-profile to either
# credential validator, so they were fail-CLOSED but wrong for the shape they
# now serve: a full_vocab credential is refused by name and k64_root is assumed
# by the validators' own default, which would have REFUSED the K0 credential the
# chain needs. No corruption was possible; the failure mode was a blocked arm.
#
# The pinning is KEPT, not removed. The caller must still DECLARE which identity
# the gate is earned in, and this helper asserts the WHOLE identity (root, K,
# block map, and the sanctioned override) rather than two of its fields. Default
# stays k64_root, so every banked K64 credential reproduces unchanged.
_fr13_assert_draft_vocab_profile() {
  local profile=$1 label=$2
  case "$profile" in
    k64_root)
      [[ "${FR13_DRAFT_VOCAB_ROOT:-}" == "1" \
         && "${FR13_DRAFT_VOCAB_K:-65536}" == "65536" \
         && "${FR13_DRAFT_VOCAB_BLOCKS:-}" == "/workspace/scripts/fr13_dvk_subset_blocks.json" \
         && -z "${FR13_NEEDS_ALLOW:-}" ]] || {
        echo "$label requires the k64_root draft-vocabulary identity: ROOT=1, K=65536, the pinned 128-id block map, and no diagnostic override" >&2
        return 1
      }
      ;;
    full_vocab)
      [[ "${FR13_DRAFT_VOCAB_ROOT:-}" == "0" \
         && "${FR13_DRAFT_VOCAB_K:-65536}" == "0" \
         && "${FR13_NEEDS_ALLOW:-}" == "FR13_DRAFT_VOCAB_K=0" ]] || {
        echo "$label requires the full_vocab draft-vocabulary identity: ROOT=0, K=0, and the sanctioned FR13_DRAFT_VOCAB_K=0 override" >&2
        return 1
      }
      ;;
    *)
      echo "$label qualification profile must be exactly k64_root or full_vocab; got: ${profile:-<empty>}" >&2
      return 1
      ;;
  esac
  return 0
}
FR13_FA2_QROW32_B1_QUALIFICATION_PROFILE=${FR13_FA2_QROW32_B1_QUALIFICATION_PROFILE:-k64_root}
FR13_FA2_QROW32_B4_QUALIFICATION_PROFILE=${FR13_FA2_QROW32_B4_QUALIFICATION_PROFILE:-k64_root}
FR13_FIXED32_GDN_SINGLE_LAUNCH_QUALIFICATION_PROFILE=${FR13_FIXED32_GDN_SINGLE_LAUNCH_QUALIFICATION_PROFILE:-k64_root}
FR13_FIXED32_GDN_GQA_GROUP3_QUALIFICATION_PROFILE=${FR13_FIXED32_GDN_GQA_GROUP3_QUALIFICATION_PROFILE:-k64_root}
FR13_FIXED32_GDN_LIVE_GATE_QUALIFICATION_PROFILE=${FR13_FIXED32_GDN_LIVE_GATE_QUALIFICATION_PROFILE:-k64_root}
MAX_NUM_SEQS=${MAX_NUM_SEQS:-4}
KV_CACHE_MEMORY_BYTES=${KV_CACHE_MEMORY_BYTES:-}
# BATCH-AWARE MEMORY (user 2026-07-06): B>=4 co-residency needs more room for KV
# (4 concurrent contexts). B=1-tuned defaults (105g cap, 0.78 util) wedged the container
# at B=4 (§76-77: exited container held ~100G unified mem). Agents are OFFLOADED to
# alienware (GB10 = vLLM-only), so the container can safely take more of the 117G box
# while still leaving OS headroom. Only auto-bumps when the caller hasn't set these.
if (( MAX_NUM_SEQS >= 4 )); then
  if [[ -z "$_FR13_DOCKER_MEM_CAP_EXPLICIT" ]]; then
    DOCKER_MEM_CAP=112g
  fi
  # SHRINK the device KV/mamba pool (user 2026-07-06). This is a GDN-HYBRID (48 mamba
  # layers vs 16 attention): the device block-pool is mostly mamba state. Measured live:
  # KV pool usage 0-6% (~3.5G peak) of a 58G reservation at 0.80 => ~16x over-provisioned.
  # On UNIFIED memory every GB reserved for KV is a GB denied to the host/system, so
  # shrinking KV frees unified room. 0.62 keeps a ~30G KV pool (~8x the observed peak,
  # ample for 4 long concurrent turns) and frees ~34G for the system => no wedge at B=4.
  if [[ -z "$_FR13_GPU_UTIL_EXPLICIT" ]]; then
    GPU_UTIL=0.62
  fi
fi
