  [[ -n "$FR13_FA2_QROW32_LIVE_PAGED_AB_ARM" ]] \
    || { echo "FR13 qrow32 live A/B requires an explicit arm" >&2; exit 2; }
else
  [[ -z "$FR13_FA2_QROW32_LIVE_PAGED_AB_ARM" ]] \
    || { echo "FR13 qrow32 live A/B arm requires the live gate" >&2; exit 2; }
fi
case "$FR13_FA2_QROW32_B1_LIVE_AB_ARM" in
  ""|nosplit|split2|visibility|gqa_pair|gqa_pair_splitk) ;;
  *) echo "FR13_FA2_QROW32_B1_LIVE_AB_ARM must be empty, nosplit, split2, visibility, gqa_pair, or gqa_pair_splitk" >&2; exit 2 ;;
esac
# ---- B1 PRODUCTION ARM PROMOTION (2026-08-13, Mark's ruling "B1 flip Yes") ----
# The B1 GQA-pair FA2 unit is the shipped B1 production kernel. It is Tier-A
# sealed (byte gate PASS + re-seals, binary pinned by 3120b3765) and timing-proven
# on real exact4 SWE-Verified traffic: step_wall 232.360 ms vs the qrow16
# incumbent 236.765 ms (-4.405 ms, -1.86%), per-request TPS 22.769 -> 23.155,
# promotion_eligible=true (output/fr13_fa2_qrow32_gqa_pair_b1_timing_20260812T073429Z).
#
# fr13_canonical_env.sh owns the VALUE -- it is the single source of truth for
# what this branch ships -- and the fallback below must never contradict it
# (tests/test_fr13_qrow32_b1_production_default.py parses both files and
# compares). The registry cannot export the selector itself: it is sourced by
# fr13_b4_campaign_driver.sh before BSIZE is known, and a B1 selector is illegal
# at B>1.
#
# So the default is applied HERE, and only in the shape where the B1 production
# selector is legal AND unambiguous:
#   * the caller did not NAME the arm (naming it empty is a deliberate opt-out
#     and is obeyed -- that is how every non-B1 arm in this tree declares itself);
#   * fixed32 Hydra27 at batch 1 / concurrency 1, the only shape in which
#     _FR13_FA2_QROW32_B1_CANDIDATE_MODE is admitted at all;
#   * not the B1 diagnostic shape (live A/B and byte work must stay explicit);
#   * no sibling FA2 private selector is engaged -- qrow16 live/production,
#     qrow32 B4 live, any B1 live A/B or timing arm, any B4 timing/production arm.
#     Those launches already name the kernel they serve; the promotion must not
#     retarget them, and the mutual-exclusion refusals below stay reachable.
# Everything downstream is unchanged and still fail-closed: the promoted arm must
# still clear the GQA-pair binary/source pins and present its sealed byte gate
# plus bound live result, or the launch is refused.
if (( _FR13_FA2_QROW32_B1_PRODUCTION_ARM_NAMED == 0 )) \
   && [[ "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" \
         && "$MAX_NUM_SEQS" == "1" \
         && "${SWE_CONCURRENCY:-}" == "1" \
         && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
         && "${FR13_FA2_QROW16_LIVE_PAGED_AB:-0}" == "0" \
         && "${FR13_FA2_QROW16_PRODUCTION:-0}" == "0" \
         && "${FR13_FA2_QROW32_LIVE_PAGED_AB:-0}" == "0" \
         && -z "$FR13_FA2_QROW32_B1_LIVE_AB_ARM" \
         && -z "$FR13_FA2_QROW32_B1_TIER_B_ARM" \
         && -z "$FR13_FA2_QROW32_B1_TIMING_ARM" \
         && -z "$FR13_FA2_QROW32_B4_TIMING_ARM" \
         && -z "$FR13_FA2_QROW32_B4_PRODUCTION_ARM" ]]; then
  # ===================================================================
  # SPLIT-K IS THE PROMOTED DEFAULT (Mark's ruling, FR14 pass 100).
  #
  # Evidence: results/fr14_nvfp4_port_20260816/splitk_fa2.md -- determinism
  # bitwise in-process and cross-process, nine pre-registered bounds cleared,
  # CLOSER to a float64 reference than the incumbent on output and LSE RMS,
  # and a clean degeneration eyeball on the round-12 traces. The exact16 QC
  # runs AFTER promotion as verification, not before it as a gate.
  #
  # Armed as a TIER-B serve, not as a production arm: the byte-exact Tier-A
  # door stays shut and _FR13_FA2_QROW32_B1_PRODUCTION_ARMS is unchanged. What
  # promotion changed is that the tier-B route is now armed BY DEFAULT.
  #
  # HARD REFUSAL, not degradation. The incumbent gqa_pair default above
  # degrades to the incumbent when its credential is stale, on the principle
  # that a promotion must never refuse a boot. That principle is inverted here
  # deliberately: a promoted default that silently serves something else is an
  # UNLABELLED A/B, and this campaign has already spent one whole round
  # (round 6) measuring the incumbent while every artifact said split-K. A
  # boot that cannot serve the promoted arm must say so and stop.
  #
  # hydra27_fixed32 only -- the same mode gate the gqa_pair default used.
  # hydra31 stays excluded topologically until its own qualification.
  if [[ -z "$FR13_FA2_QROW32_B1_TIER_B_ARM" ]]; then
    FR13_FA2_QROW32_B1_TIER_B_ARM=$_FR13_SPLITK_DEFAULT_ARM
    # SITE 15. Take back whatever the credential pointer imported before this
    # block ever ran, THEN assign. Either half would do; both are here because
    # the failure mode is silent and cost a boot.
    _fr13_b1_withdraw_pointer_imports
    FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST=${FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST:-$_FR13_SPLITK_DEFAULT_CREDENTIAL}
    FORKED_FA2_SO=${FORKED_FA2_SO:-$_FR13_SPLITK_DEFAULT_SO}
    # THE BINARY PINS ARE OWNED, NOT DEFAULTED. These six describe the exact
    # .so this default stages and verifies three lines below; a leftover value
    # describing some other binary is never the right answer, so there is no
    # ':-' here and there must never be one. FORKED_FA2_SO keeps its ':-'
    # deliberately -- the path is where the operator staged the file, the pins
    # are what the file must BE.
    FR13_FA2_QROW32_B1_SO_SHA256=$_FR13_SPLITK_DEFAULT_SO_SHA256
    FR13_FA2_QROW32_B1_SO_SIZE=$_FR13_SPLITK_DEFAULT_SO_SIZE
    FR13_FA2_QROW32_B1_FA2_HEAD=$_FR13_SPLITK_DEFAULT_FA2_HEAD
    FR13_FA2_QROW32_B1_SOURCE_CLOSURE_SHA256=$_FR13_SPLITK_DEFAULT_CLOSURE
    FR13_FA2_QROW32_B1_SPLITK_SASS_DIGEST=$_FR13_SPLITK_DEFAULT_SASS
    FR13_FA2_QROW32_B1_SPLITK_BASELINE_SASS_DIGEST=$_FR13_SPLITK_DEFAULT_BASELINE_SASS
    [[ -f "$FORKED_FA2_SO" && ! -L "$FORKED_FA2_SO" \
       && "$(sha256sum "$FORKED_FA2_SO" | cut -d' ' -f1)" == "$_FR13_SPLITK_DEFAULT_SO_SHA256" ]] || {
      echo "FR13 promoted split-K default: staged binary missing or not the pinned kernel: $FORKED_FA2_SO" >&2
      echo "  a promoted default must not silently serve the incumbent instead" >&2
      exit 2
    }
    [[ -f "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" \
       && ! -L "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" ]] || {
      echo "FR13 promoted split-K default: tier-b credential missing: $FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" >&2
      exit 2
    }
    FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_SHA256=${FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_SHA256:-$(sha256sum "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" | cut -d' ' -f1)}
    # F1 (severity-1, pass 106). Arming a selector is not the same as
    # surviving it. This block set TIER_B_ARM and nothing else, so
    # SELECTOR_COUNT became 1 and the selector gate below then demanded
    # SOURCE_COMMIT and PATCH_SOURCE_SHA256 that nobody had set -- every plain
    # hydra27 B1 launch exited 2, and the promoted default had never once
    # served. Round 12 named the arm explicitly, which is why it booted.
    #
    # The gqa_pair default answers this by requiring the CALLER to have
    # presented provenance and standing down when it is stale. A hard-refusal
    # default cannot stand down, so it MINTS instead: there is no caller
    # declaration to check here, because the launcher itself is the thing
    # arming, from its own literals. What actually guards the binary is the
    # sha/size/SASS check above and verify-tier-b on the credential -- neither
    # of which a minted commit can weaken.
    FR13_FA2_QROW32_B1_SOURCE_COMMIT=${FR13_FA2_QROW32_B1_SOURCE_COMMIT:-$(git rev-parse HEAD 2>/dev/null || echo "")}
    # SITE 16. This used to mint the patcher digest BY HASHING THE PATCHER --
    # the same file the selector gate then compares against disk. A value
    # derived from an artifact cannot test that artifact: the gate was
    # disk-vs-disk, i.e. `x == x`, and could not fail however stale the
    # credential was. It is now minted from the CREDENTIAL'S SEALED IDENTITY,
    # so the gate becomes sealed-vs-disk and actually asks the question it
    # looks like it is asking: is the patcher on disk the one this credential
    # was earned against?
    #
    # Read with grep rather than a JSON parser on purpose: this runs on the
    # host before docker and must not acquire a Python dependency. The value
    # is constrained to 64 hex chars by the pattern itself, and the credential
    # file's own digest is verified at the tier-B serve gate below.
    FR13_FA2_QROW32_B1_PATCH_SOURCE_SHA256=${FR13_FA2_QROW32_B1_PATCH_SOURCE_SHA256:-$(
      grep -o '"patch_source_sha256"[[:space:]]*:[[:space:]]*"[0-9a-f]\{64\}"' \
           "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" \
        | head -n 1 | grep -o '[0-9a-f]\{64\}')}
    [[ "$FR13_FA2_QROW32_B1_PATCH_SOURCE_SHA256" =~ ^[0-9a-f]{64}$ ]] || {
      echo "FR13 promoted split-K default: the tier-b credential carries no" \
           "patch_source_sha256 identity to mint from:" \
           "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" >&2
      exit 2
    }
    [[ -n "$FR13_FA2_QROW32_B1_SOURCE_COMMIT" ]] || {
      echo "FR13 promoted split-K default: cannot mint the selector provenance (no git HEAD)" >&2
      exit 2
    }
    echo "[fr13] B1 arm unnamed; serving the PROMOTED DEFAULT" \
         "FR13_FA2_QROW32_B1_TIER_B_ARM=$FR13_FA2_QROW32_B1_TIER_B_ARM" \
         "(tier-b credential $FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_SHA256)" >&2
  fi
  # F2 ARBITRATION (severity-1, pass 106). Two promoted defaults could arm at
  # once -- a caller presenting a gqa_pair credential got TIER_B_ARM from the
  # block above AND PRODUCTION_ARM here, SELECTOR_COUNT=2, and a refusal with
  # no arbitration between them. Split-K's default SUPERSEDES gqa_pair's: it
  # IS the promotion. Naming gqa_pair explicitly is untouched -- this whole
  # region runs only when no arm was named.
  if [[ -n "$FR13_FA2_QROW32_B1_TIER_B_ARM" ]]; then
    echo "[fr13] gqa_pair promoted default STANDS DOWN: the split-K tier-b" \
         "default is armed (split-K supersedes; name gqa_pair explicitly to opt out)" >&2
  else
  FR13_FA2_QROW32_B1_PRODUCTION_ARM=${FR13_FA2_QROW32_B1_PRODUCTION_ARM_DEFAULT:-gqa_pair}
  echo "[fr13] B1 production arm unnamed; serving the promoted default" \
       "FR13_FA2_QROW32_B1_PRODUCTION_ARM=$FR13_FA2_QROW32_B1_PRODUCTION_ARM" >&2
  fi
fi
case "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" in
  ""|nosplit|gqa_pair) ;;
  *) echo "FR13_FA2_QROW32_B1_PRODUCTION_ARM must be empty, nosplit, or gqa_pair" >&2; exit 2 ;;
esac
case "$FR13_FA2_QROW32_B1_TIMING_ARM" in
  ""|qrow16_stock|gqa_pair) ;;
  *) echo "FR13_FA2_QROW32_B1_TIMING_ARM must be empty, qrow16_stock, or gqa_pair" >&2; exit 2 ;;
esac
# Unlike the B4 pair -- where both arms load one binary and the sentinel is the
# only delta -- the B1 pair spans TWO binaries: the stock arm is the qrow16
# incumbent production path in the qrow16 .so, and the candidate arm is the
# GQA-pair .so with the sentinel injected. The timing arm names which side of
# that pair this launch is, so the binary pins and the selector cannot disagree.
if [[ "$FR13_FA2_QROW32_B1_TIMING_ARM" == "gqa_pair" \
      && "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" != "gqa_pair" ]]; then
  echo "FR13 qrow32 B1 gqa_pair timing arm must serve the candidate" >&2
  exit 2
fi
if [[ "$FR13_FA2_QROW32_B1_TIMING_ARM" == "qrow16_stock" ]]; then
  # The stock reference must be the untouched qrow16 incumbent: no B1 selector
  # of any kind, or the "stock" side is not stock.
  if [[ -n "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" \
        || -n "$FR13_FA2_QROW32_B1_TIER_B_ARM" \
        || -n "$FR13_FA2_QROW32_B1_LIVE_AB_ARM" ]]; then
    echo "FR13 qrow32 B1 qrow16_stock timing arm must carry no B1 selector" >&2
    exit 2
  fi
  if [[ "$FR13_FA2_QROW16_PRODUCTION" != "1" ]]; then
    echo "FR13 qrow32 B1 qrow16_stock timing arm requires qrow16 production" >&2
    exit 2
  fi
fi
# PROMOTION 2026-08-13 relaxed this clause, and only this clause. It used to read
# `!= "gqa_pair"`, which made the GQA-pair production arm reachable ONLY from
# inside the timing pair -- correct while the arm was a candidate, and fatal the
# moment it becomes the shipped default, because production serving carries no
# timing arm at all. The pairing invariant it protected is untouched: a NAMED
# timing arm must still agree with the served kernel (the `gqa_pair timing arm
# must serve the candidate` clause above, and `qrow16_stock` refusing any B1
# selector), and the binary is pinned independently by _FR13_FA2_QROW32_B1_PIN_ARM,
# which resolves the .so from the production arm when no live arm is set. What is
# now allowed is exactly the empty timing arm: a plain B1 production serve.
if [[ "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" == "gqa_pair" \
      && -n "$FR13_FA2_QROW32_B1_TIMING_ARM" \
      && "$FR13_FA2_QROW32_B1_TIMING_ARM" != "gqa_pair" ]]; then
  echo "FR13 qrow32 B1 GQA-pair production requires the gqa_pair timing arm" >&2
  exit 2
fi
if [[ -n "${FR13_FA2_QROW16_INTERNAL_DISPATCH:-}" \
      || -n "${FR13_FA2_QROW16_INTERNAL_PRODUCTION_ATTESTED:-}" ]]; then
  echo "FR13 qrow16 internal selectors are launcher-private" >&2
  exit 2
fi
if [[ -n "${FR13_FA2_QROW32_B1_INTERNAL_ATTESTED:-}" ]]; then
  echo "FR13 qrow32 B1 internal attestation is launcher-private" >&2
  exit 2
fi
case "$FR13_FA2_QROW32_B4_TIMING_ARM" in
  ""|stock_dispatch|gqa_pair) ;;
  *) echo "FR13_FA2_QROW32_B4_TIMING_ARM must be empty, stock_dispatch, or gqa_pair" >&2; exit 2 ;;
esac
# ---- B4 PRODUCTION ARM PROMOTION (2026-08-14, Mark's B4 default flip ruling) ----
# The PADDED GQA-pair FA2 unit is the shipped B4 production kernel. It is sealed
# at candidate_scope final_fixed32_b34_full_graph_only with production_widths 3
# and 4, and it is timing-proven on real SWE-Verified traffic: the four-pass
# Hydra27 sealing campaign (output/fr13_b4_hydra27_sealing_campaign_20260814T011514Z)
# returned SEALED_HYDRA27_GAIN -- batch-conditioned width-4 improvement mean
# 27.03 ms/step with a one-sided 95% lower bound of 10.82 ms/step over n=4 passes
# of balanced SC/CS arm order, placebo width clean in every pass -- and the padded
# pair (output/fr13_b4_width4_timing_padded_20260813T201426Z) put width 3 at
# 25.16 ms/step against a pre-registered 25.6 +/- 3.5. Agent behaviour was held
# by the exact16 QC PASS (results/fr13_b4_exact16_qc_20260814, 9/16 = the
# historical median, zero giveups).
#
# fr13_canonical_env.sh owns the VALUE -- it is the single source of truth for
# what this branch ships -- and the fallback below must never contradict it
# (tests/test_fr13_qrow32_b4_production_default.py parses both files and
# compares). The registry cannot export the selector itself: it is sourced before
# BSIZE is known, and the B4 production selector is a CREDENTIALED selector that
# the launcher must refuse wherever no sealed dual gate was presented.
#
# So the default is applied HERE, and only in the shape where the B4 production
# selector is legal AND unambiguous:
#   * the caller did not NAME the arm (naming it empty is a deliberate opt-out
#     and is obeyed -- it is how the stock side of the width-4 timing pair says
#     "load the candidate binary, serve the stock dispatch");
#   * fixed32 at batch 4 / concurrency 4, the only shape in which
#     _FR13_FA2_QROW32_B4_CANDIDATE_MODE is admitted at all, and not the B1
#     diagnostic shape;
#   * the launch PRESENTED the sealed b34 dual raw-byte gate. This clause is the
#     B4-specific half of the scope and it is what keeps the promotion honest.
#     B=1/concurrency 1 is a rare shape, so the B1 promotion at 99a511319 could
#     key on batch alone and excluded its handful of siblings by diagnostic flag
#     or by an explicit opt-out. B=4/concurrency 4 fixed32 is the shape of the
#     ENTIRE campaign -- every floor gate, GDN/CUTLASS/SFWD timing pair, live
#     gate and nsys profile in this tree runs it -- and none of them can serve
#     this kernel, because none of them holds its credential. Promoting on batch
#     alone would hand all of them a selector the credential chain must then
#     refuse at boot. The sealed gate is the thing that distinguishes a
#     production serve from a campaign arm, so it is what the promotion keys on;
#   * no sibling FA2 private selector is engaged -- qrow16 live/production,
#     qrow32 live A/B (which is how the b34 byte gate itself runs), any B1 live
#     A/B, timing or production arm, or a B4 timing arm. Those launches already
#     name the kernel they serve, and the mutual-exclusion refusals below stay
#     reachable.
# Everything downstream is unchanged and still fail-closed: the promoted arm must
# still clear the pinned binary/source identity, the byte-pinned canonical
# evidence set, and its bound dual raw-byte gate, or the launch is refused.
if (( _FR13_FA2_QROW32_B4_PRODUCTION_ARM_NAMED == 0 )) \
   && [[ ( "${FR13_FIXED32_MODE:-}" == "tail6_fixed32" \
           || "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" ) \
         && "$MAX_NUM_SEQS" == "4" \
         && "${SWE_CONCURRENCY:-}" == "4" \
         && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
         && -n "$FR13_FA2_QROW32_B4_DUAL_GATE_JSON" \
         && -n "$FR13_FA2_QROW32_B4_DUAL_GATE_SHA256" \
         && "${FR13_FA2_QROW16_LIVE_PAGED_AB:-0}" == "0" \
         && "${FR13_FA2_QROW16_PRODUCTION:-0}" == "0" \
         && "${FR13_FA2_QROW32_LIVE_PAGED_AB:-0}" == "0" \
         && -z "$FR13_FA2_QROW32_B1_LIVE_AB_ARM" \
         && -z "$FR13_FA2_QROW32_B1_TIER_B_ARM" \
         && -z "$FR13_FA2_QROW32_B1_TIMING_ARM" \
         && -z "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" \
         && -z "$FR13_FA2_QROW32_B4_TIMING_ARM" ]]; then
  FR13_FA2_QROW32_B4_PRODUCTION_ARM=${FR13_FA2_QROW32_B4_PRODUCTION_ARM_DEFAULT:-gqa_pair}
  echo "[fr13] B4 production arm unnamed; serving the promoted default" \
       "FR13_FA2_QROW32_B4_PRODUCTION_ARM=$FR13_FA2_QROW32_B4_PRODUCTION_ARM" >&2
fi
case "$FR13_FA2_QROW32_B4_PRODUCTION_ARM" in
  ""|gqa_pair) ;;
  *) echo "FR13_FA2_QROW32_B4_PRODUCTION_ARM must be empty or gqa_pair" >&2; exit 2 ;;
esac
# The timing pair is a single-variable delta: BOTH arms load the identical
# pinned GQA-pair binary, and only the served kernel selector changes. The
# timing arm declares the binary; the production arm decides whether the
# sentinel is injected. They must agree exactly, or the pair is not paired.
if [[ "$FR13_FA2_QROW32_B4_TIMING_ARM" == "gqa_pair" \
      && "$FR13_FA2_QROW32_B4_PRODUCTION_ARM" != "gqa_pair" ]]; then
  echo "FR13 qrow32 B4 gqa_pair timing arm must serve the candidate" >&2
  exit 2
fi
# PROMOTION 2026-08-14 relaxed this clause, and only this clause. It used to read
# `!= "gqa_pair"`, which made the GQA-pair production arm reachable ONLY from
# inside the timing pair -- correct while the arm was a candidate, and fatal the
# moment it becomes the shipped default, because production serving carries no
# timing arm at all. The pairing invariant it protected is untouched: a NAMED
# timing arm must still agree with the served kernel (the `gqa_pair timing arm
# must serve the candidate` clause above), and the binary is pinned independently
# by the candidate-mode preflight, which the promotion extends to cover a
# production launch that carries no timing arm. What is now allowed is exactly
# the empty timing arm: a plain B4 production serve.
if [[ "$FR13_FA2_QROW32_B4_PRODUCTION_ARM" == "gqa_pair" \
      && -n "$FR13_FA2_QROW32_B4_TIMING_ARM" \
      && "$FR13_FA2_QROW32_B4_TIMING_ARM" != "gqa_pair" ]]; then
  echo "FR13 qrow32 B4 production requires the gqa_pair timing arm" >&2
  exit 2
fi
if [[ -n "${FR13_FA2_QROW32_B4_INTERNAL_ATTESTED:-}" ]]; then
  echo "FR13 qrow32 B4 internal attestation is launcher-private" >&2
  exit 2
fi
if [[ "${_FR13_CALLER_M32_GUARD[FR13_FA2_QROW32_B1_PRODUCTION_PASS_SIDECAR]}" == set:* \
      || "${_FR13_CALLER_M32_GUARD[FR13_FA2_QROW32_B1_PRODUCTION_PASS_SIDECAR_SHA256]}" == set:* \
      || "${_FR13_CALLER_M32_GUARD[FR13_FA2_QROW32_B4_PRODUCTION_PASS_SIDECAR]}" == set:* \
      || "${_FR13_CALLER_M32_GUARD[FR13_FA2_QROW32_B4_PRODUCTION_PASS_SIDECAR_SHA256]}" == set:* ]]; then
  echo "FR13 qrow32 production sidecar credentials are launcher-private" >&2
  exit 2
fi
unset _FR13_CALLER_M32_GUARD
if [[ "$FR13_FA2_QROW16_LIVE_PAGED_AB" == "1" \
      && "$FR13_FA2_QROW16_PRODUCTION" == "1" ]]; then
  echo "FR13 qrow16 live A/B and production are mutually exclusive" >&2
  exit 2
fi
if [[ "$FR13_FA2_QROW32_LIVE_PAGED_AB" == "1" \
      && ( "$FR13_FA2_QROW16_LIVE_PAGED_AB" == "1" \
           || "$FR13_FA2_QROW16_PRODUCTION" == "1" ) ]]; then
  echo "FR13 qrow32 live A/B and qrow16 selectors are mutually exclusive" >&2
  exit 2
fi
_FR13_FA2_QROW32_B1_SELECTOR_COUNT=0
[[ -z "$FR13_FA2_QROW32_B1_LIVE_AB_ARM" ]] || ((_FR13_FA2_QROW32_B1_SELECTOR_COUNT+=1))
[[ -z "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" ]] || ((_FR13_FA2_QROW32_B1_SELECTOR_COUNT+=1))
# TIER-B SERVE: a first-class selector, not a modifier of the live-A/B one.
# Sites 17-20 all trace to spelling it as LIVE_AB_ARM plus a flag: every gate
# in the tree then had to be read twice, once as "shadow" and once as "serve",
# and one of the two readings was missed each time.
[[ -z "$FR13_FA2_QROW32_B1_TIER_B_ARM" ]] || ((_FR13_FA2_QROW32_B1_SELECTOR_COUNT+=1))
[[ "${FR13_FA2_QROW32_B1_TIER_B_SERVE:-0}" == "0" ]] || {
  echo "FR13_FA2_QROW32_B1_TIER_B_SERVE is retired; use FR13_FA2_QROW32_B1_TIER_B_ARM=<arm>" >&2
  exit 2
}
case "$FR13_FA2_QROW32_B1_TIER_B_ARM" in
  ""|gqa_pair_splitk) ;;
  *) echo "FR13_FA2_QROW32_B1_TIER_B_ARM must be empty or gqa_pair_splitk" >&2; exit 2 ;;
esac
