  # a launch that serves it with NO timing arm, and that launch would otherwise
  # have skipped -- silently -- the .so digest and size pins, the FA2 head and
  # source-closure pins, the on-disk re-hash of $FORKED_FA2_SO, SOURCE_COMMIT ==
  # git rev-parse HEAD, the patcher digest, the batch-4/concurrency-4 and
  # FULL_AND_PIECEWISE runtime shape, the K64/root1 DVK identity, and the
  # byte-pinned evidence-set predicate. Every one of those is a precondition of
  # the credential the launch is about to be issued: the issuance below signs
  # $FR13_FA2_QROW32_SO_SHA256 and $FR13_FA2_QROW32_SOURCE_COMMIT, which are
  # caller-supplied and, without this block, caller-CHECKED by nothing. Promotion
  # must not turn a gated candidate into an ungated default, so the gate moves
  # with it.
  _FR13_FA2_QROW32_B4_CANDIDATE_MODE=1
  # THE QUALIFIED THING IS A GEOMETRY, NOT A TASK LIST.  The dual raw-byte gate
  # qualified the final fixed32 B4 FULL graph: 4 slots x 32 physical rows = 128
  # query rows, 16 target layers, batch stride 0x20014.  A 16-task pool at 4
  # slots serves that IDENTICAL geometry -- MAX_NUM_SEQS and SWE_CONCURRENCY are
  # still pinned to 4 below -- and exact4 is literally the first four entries of
  # that pool.  What differs is only how often a finishing task is replaced
  # instead of letting the served width decay.
  #
  # So this predicate admits exactly the two byte-pinned campaign evidence sets
  # (fr13_floor_gate.EVIDENCE_SETS 4 and 16) and NOTHING else: an unpinned task
  # list would let an arm serve traffic whose shape was never qualified, which
  # is the precise failure this check exists to prevent.  The pair must match a
  # set ENTIRELY -- ids AND digest -- so an exact4 digest cannot be paired with a
  # 16-task list.
  _FR13_FA2_QROW32_B4_TASK_SET=
  case "${FR13_FA2_QROW32_B4_EXACT4_TASK_IDS}|${FR13_FA2_QROW32_B4_EXACT4_SUBSET_SHA256}" in
    "astropy__astropy-12907,astropy__astropy-13033,astropy__astropy-13236,astropy__astropy-13398|0e37b7137115332372ef76ba7c8db0db4a46ebad5db777c5b999bf797ae853f5")
      _FR13_FA2_QROW32_B4_TASK_SET=exact4 ;;
    "astropy__astropy-12907,astropy__astropy-13033,astropy__astropy-13236,astropy__astropy-13398,astropy__astropy-13453,astropy__astropy-13579,astropy__astropy-13977,astropy__astropy-14096,astropy__astropy-14182,astropy__astropy-14309,astropy__astropy-14365,astropy__astropy-14369,astropy__astropy-14508,astropy__astropy-14539,astropy__astropy-14598,astropy__astropy-14995|47b0a3c9be49e2cb5f7e7217ae03c267a05359f269f3e3b038942f57d7dc0b5c")
      _FR13_FA2_QROW32_B4_TASK_SET=pool16 ;;
  esac
  _fr13_assert_draft_vocab_profile \
    "$FR13_FA2_QROW32_B4_QUALIFICATION_PROFILE" "FR13 qrow32 B4 GQA-pair" || exit 2
  [[ ( "${FR13_FIXED32_MODE:-}" == "tail6_fixed32" \
       || "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" ) \
     && "$MAX_NUM_SEQS" == "4" \
     && "${SWE_CONCURRENCY:-}" == "4" \
     && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
     && "${ENFORCE_EAGER:-0}" == "0" \
     && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" \
     && "$FR13_FA2_QROW32_SO_SHA256" == "af9e9f24335db899468032f5b5a3eba100febe294932533cb9b87163ce2b3fdb" \
     && "$FR13_FA2_QROW32_SO_SIZE" == "299813360" \
     && "$FR13_FA2_QROW32_FA2_HEAD" == "29210221863736a08f71a866459e368ad1ac4a95" \
     && "$FR13_FA2_QROW32_SOURCE_CLOSURE_SHA256" == "9c3f9e751da7b783e9d07d8e40d5bc2234b99e719a1048668bd6c82244ed2d81" \
     && "$(sha256sum "$FORKED_FA2_SO" | cut -d' ' -f1)" == "$FR13_FA2_QROW32_SO_SHA256" \
     && "$(stat -c '%s' "$FORKED_FA2_SO")" == "$FR13_FA2_QROW32_SO_SIZE" \
     && "$FR13_FA2_QROW32_SOURCE_COMMIT" =~ ^[0-9a-f]{40}$ \
     && "$FR13_FA2_QROW32_SOURCE_COMMIT" == "$(git rev-parse HEAD)" \
     && "$FR13_FA2_QROW32_B4_PATCH_SOURCE_SHA256" == "$(sha256sum scripts/fr13_patch_fa2_tree_bias.py | cut -d' ' -f1)" \
     && -n "$_FR13_FA2_QROW32_B4_TASK_SET" ]] || {
    echo "FR13 qrow32 B4 GQA-pair timing or production requires a byte-pinned canonical B4 evidence set (exact4 or pool16) and pinned binary/source provenance" >&2
    exit 2
  }
  echo "FR13 qrow32 B4 evidence set: $_FR13_FA2_QROW32_B4_TASK_SET" >&2
fi
if [[ -n "$FR13_FA2_QROW32_B4_PRODUCTION_ARM" ]]; then
  [[ -f "$FR13_FA2_QROW32_B4_DUAL_GATE_JSON" \
     && ! -L "$FR13_FA2_QROW32_B4_DUAL_GATE_JSON" \
     && "$FR13_FA2_QROW32_B4_DUAL_GATE_SHA256" =~ ^[0-9a-f]{64}$ \
     && "$(sha256sum "$FR13_FA2_QROW32_B4_DUAL_GATE_JSON" | cut -d' ' -f1)" == "$FR13_FA2_QROW32_B4_DUAL_GATE_SHA256" ]] || {
    echo "FR13 qrow32 B4 production requires its bound dual raw-byte gate PASS" >&2
    exit 2
  }
fi
_FR13_FA2_QROW32_B1_CANDIDATE_MODE=0
if (( _FR13_FA2_QROW32_B1_SELECTOR_COUNT > 0 )); then
  _FR13_FA2_QROW32_B1_CANDIDATE_MODE=1
  # RECONCILED WITH PASS 101 (F1, pass 106). This gate demanded
  # SOURCE_COMMIT == HEAD for every B1 selector -- the commit-binding the
  # tier-B credential DROPPED when split-K was promoted. A credential that
  # attests numerics must bind what can change them, and a commit that touches
  # no kernel input cannot. Leaving the gate enforcing a rule the credential no
  # longer makes would re-impose it one layer down where nothing documents it,
  # so the two are made to agree, in the credential's direction. The PATCHER
  # digest below is still checked for every arm including tier-B: it decides
  # dispatch, and the credential binds it too. Only the commit clause is scoped.
  _fr13_b1_commit_bound=1
  [[ -z "$FR13_FA2_QROW32_B1_TIER_B_ARM" ]] || _fr13_b1_commit_bound=0
  _fr13_assert_draft_vocab_profile \
    "$FR13_FA2_QROW32_B1_QUALIFICATION_PROFILE" "FR13 qrow32 B1 selector" || exit 2
  [[ "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" \
     && "$MAX_NUM_SEQS" == "1" \
     && "${SWE_CONCURRENCY:-}" == "1" \
     && "$FR13_FA2_QROW32_B1_PATCH_SOURCE_SHA256" == "$(sha256sum scripts/fr13_patch_fa2_tree_bias.py | cut -d' ' -f1)" \
     && "$(stat -c '%s' "$FORKED_FA2_SO")" == "$FR13_FA2_QROW32_B1_SO_SIZE" ]] || {
    echo "FR13 qrow32 B1 selector requires Hydra27 B1 and exact binary/source provenance" >&2
    exit 2
  }
  if (( _fr13_b1_commit_bound == 1 )); then
    [[ "$FR13_FA2_QROW32_B1_SOURCE_COMMIT" == "$(git rev-parse HEAD)" ]] || {
      echo "FR13 qrow32 B1 selector requires a credential earned at this HEAD" >&2
      exit 2
    }
  else
    [[ "$FR13_FA2_QROW32_B1_SOURCE_COMMIT" =~ ^[0-9a-f]{40}$ ]] || {
      echo "FR13 qrow32 B1 tier-b selector requires a well-formed source commit" >&2
      exit 2
    }
  fi
  # Each B1 arm carries its own binary + source-closure pins. Resolve the arm
  # that actually decides which binary is loaded: a production launch has no
  # live arm, so keying on the live arm alone would silently check a GQA-pair
  # production run against the incumbent no-split pins.
  _FR13_FA2_QROW32_B1_PIN_ARM=$FR13_FA2_QROW32_B1_LIVE_AB_ARM
  if [[ -z "$_FR13_FA2_QROW32_B1_PIN_ARM" ]]; then
    _FR13_FA2_QROW32_B1_PIN_ARM=$FR13_FA2_QROW32_B1_TIER_B_ARM
  fi
  if [[ -z "$_FR13_FA2_QROW32_B1_PIN_ARM" ]]; then
    _FR13_FA2_QROW32_B1_PIN_ARM=$FR13_FA2_QROW32_B1_PRODUCTION_ARM
  fi
  # Spelled OUT, like its Python twin. "" was both "no selector named" and
  # "a resolver that failed to look", and site 23 is what happens when those
  # two are the same value. They are now different: this is "nosplit", and a
  # resolver that fails to look refuses.
  if [[ -z "$_FR13_FA2_QROW32_B1_PIN_ARM" ]]; then
    _FR13_FA2_QROW32_B1_PIN_ARM=nosplit
  fi
  case "$_FR13_FA2_QROW32_B1_PIN_ARM" in
    visibility)
      [[ "$FR13_FA2_QROW32_B1_SO_SHA256" == "c5ab32a6ae4e615f1e77a4997db5429152053c549e761fb11d90b33bb3959a79" \
         && "$FR13_FA2_QROW32_B1_SO_SIZE" == "300200192" \
         && "$FR13_FA2_QROW32_B1_FA2_HEAD" == "29210221863736a08f71a866459e368ad1ac4a95" \
         && "$FR13_FA2_QROW32_B1_SOURCE_CLOSURE_SHA256" == "a30eca031cd5067133e6278527787c5987635670930e5840ac983f66b088e4fc" ]] || {
        echo "FR13 qrow32 B1 visibility binary/source provenance drifted" >&2
        exit 2
      }
      ;;
    gqa_pair)
      # The GQA-pair B1 unit is one translation unit derived from the
      # byte-qualified B4 sibling, so its closure digest is its own.
      [[ "$FR13_FA2_QROW32_B1_SO_SHA256" == "3560cdc0c1ebbe3d912858ea447b350edefc0d6749950d6353e5f763185da6ae" \
         && "$FR13_FA2_QROW32_B1_SO_SIZE" == "299815552" \
         && "$FR13_FA2_QROW32_B1_FA2_HEAD" == "29210221863736a08f71a866459e368ad1ac4a95" \
         && "$FR13_FA2_QROW32_B1_SOURCE_CLOSURE_SHA256" == "172b5e7131841ce45650bb8eea35f0b427ca660ce8f145bd39b55b00a336ebf4" ]] || {
        echo "FR13 qrow32 B1 GQA-pair binary/source provenance drifted" >&2
        exit 2
      }
      ;;
    gqa_pair_splitk)
      # ---- FR14 lane 4 split-K (Tier-B, GATE-ONLY, never a production arm) ----
      # Splitting the context walk four ways changes per-row accumulation order,
      # so this arm is structurally refused by the raw-byte gate
      # (_fr13_fa2_qrow32_b1_require_same_reduction) -- correctly. It is reachable
      # only as a LIVE arm, for the generation probe and eyeball Mark's condition
      # requires, and it is deliberately absent from the production-arm case below.
      # Identity from results/fr14_nvfp4_port_20260816/splitk_fa2.md 8 and
      # fr14_splitk_fa2_build_attestation.json.
      [[ "$FR13_FA2_QROW32_B1_SO_SHA256" == "28570f835ea72c99d03aab9fb03c494388bbb9c264ee4dc96eec047f50d7f857" \
         && "$FR13_FA2_QROW32_B1_SO_SIZE" == "300123792" \
         && "$FR13_FA2_QROW32_B1_FA2_HEAD" == "29210221863736a08f71a866459e368ad1ac4a95" \
         && "$FR13_FA2_QROW32_B1_SOURCE_CLOSURE_SHA256" == "4ed00909cef7ea83849f897018ea4f6a14119b8d160927af426938920c170878" ]] || {
        echo "FR13 qrow32 B1 split-K binary/source provenance drifted" >&2
        exit 2
      }
      # The .so sha is NOT rebuild-reproducible for this arm: four links from one
      # closure produced two .so hashes at an identical 300123792 bytes (the nvcc
      # container-PID stamp). The SASS digests are what attest that the KERNEL
      # reproduced, so they are pinned here alongside the artifact -- including the
      # BASELINE digest, which is what makes "the split-K header edits are inert at
      # Split=false" a measurement rather than a claim.
      [[ "$FR13_FA2_QROW32_B1_SPLITK_SASS_DIGEST" == "3f24d70dce2ff70ad9209bad5af2a93cc39453df529cb298e4476cbfbfd80b9e" \
         && "$FR13_FA2_QROW32_B1_SPLITK_BASELINE_SASS_DIGEST" == "fa01f98840420b9c0177d06297aacabb0ed5e00c674511fdaa4aa618c3473470" ]] || {
        echo "FR13 qrow32 B1 split-K SASS credential drifted (kernel and/or sealed baseline)" >&2
        exit 2
      }
      # Re-hash the binary actually being mounted. The B1 selector above only
      # compares its SIZE, and this arm's two known links differ in sha at
      # identical size -- exactly the case a size check cannot separate. Symlinks
      # are refused for the same reason the gate-JSON credentials refuse them.
      [[ -f "$FORKED_FA2_SO" \
         && ! -L "$FORKED_FA2_SO" \
         && "$(sha256sum "$FORKED_FA2_SO" | cut -d' ' -f1)" == "$FR13_FA2_QROW32_B1_SO_SHA256" ]] || {
        echo "FR13 qrow32 B1 split-K requires the pinned .so present and byte-identical: $FORKED_FA2_SO" >&2
        exit 2
      }
      ;;
    nosplit|split2|"")
      # nosplit and split2 genuinely share one binary. They are NAMED here
      # rather than left to a default, because the default is what made the
      # 17th site possible: a `*)` that asserts an arm's pins answers for every
      # arm nobody wrote a branch for, and answers with the WRONG identity.
      [[ "$FR13_FA2_QROW32_B1_SO_SHA256" == "a9d8a6887b8b27b3a83af60bba7945eb66caff174ba710c2ee2aea92b8e7081a" \
         && "$FR13_FA2_QROW32_B1_SO_SIZE" == "300154616" \
         && "$FR13_FA2_QROW32_B1_FA2_HEAD" == "29210221863736a08f71a866459e368ad1ac4a95" \
         && "$FR13_FA2_QROW32_B1_SOURCE_CLOSURE_SHA256" == "22b8c2016443a151bf50f62166f7cc3b9ce45137138d948b76fdfded74c395ff" ]] || {
        echo "FR13 qrow32 B1 incumbent candidate provenance drifted" >&2
        exit 2
      }
      ;;
    *)
      # An arm with no branch here has no pinned identity, and an unpinned
      # identity must REFUSE rather than inherit one.
      echo "FR13 qrow32 B1 pin arm has no pinned identity: $_FR13_FA2_QROW32_B1_PIN_ARM" >&2
      exit 2
      ;;
  esac
fi
if [[ -n "$FR13_FA2_QROW32_B1_LIVE_AB_ARM" ]]; then
  [[ "$FR13_FA2_QROW32_B1_LIVE_AB_INSTANCE_ID" == "astropy__astropy-12907" \
     && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "1" \
     && "${ENFORCE_EAGER:-0}" == "0" \
     && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" \
     && -z "${FR13_NEEDS_ALLOW:-}" \
     && "$FR13_FIXED32_TAW_NATIVE_PRECOMPUTE" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB:-0}" == "0" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_CANDIDATE:-}" \
     && "${FR13_FIXED32_SFWD_STATE_FUSION_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_SFWD_CONV_POSTPREP_FUSION:-0}" == "0" \
     && "${FR13_FIXED32_SFWD_CONV_POSTPREP_BYTE_AB:-0}" == "0" \
     && "${FR13_CFWD_LOGIT_DIRECT_BYTE_AB:-0}" == "0" \
     && "${FR13_CFWD_LOGIT_DIRECT_PRODUCTION:-0}" == "0" \
     && "${FR13_FIXED32_CUTLASS_WAVE:-stock}" == "stock" \
     && "${FR13_DFWD_UNIFIED_BM8_LIVE_AB:-0}" == "0" \
     && "${FR13_DRAFT_HEAD_M32_LIVE_AB:-0}" == "0" \
     && ( -z "${FR13_FIXED32_GDN_PATH_BV_CANDIDATE:-}" \
          || ( ( "${FR13_FIXED32_GDN_PATH_BV_CANDIDATE:-}" == "gqa_group3" \
                 || "${FR13_FIXED32_GDN_PATH_BV_CANDIDATE:-}" == "gqa_group3_bv16" ) \
               && "${FR13_FIXED32_GDN_SINGLE_LAUNCH_EXPECTED_BATCH:-}" == "1" \
               && "${FR13_DFWD_K64_TOP3:-0}" == "1" \
               && "$FR10_METRICS" == "1" ) ) ]] || {
    echo "FR13 qrow32 B1 live gate requires the canonical K64/root1 real task and only the admitted GQA3/top3 graph tuple" >&2
    exit 2
  }
fi
if [[ -n "$FR13_FA2_QROW32_B1_TIER_B_ARM" ]]; then
  # SITE 20's CONTRADICTION, RULED (coordinator, pass 74): tier-B SERVING
  # carries the CANONICAL EXACT4 CAMPAIGN IDENTITY like any campaign serve --
  # the paired multi-task A/B is the route's purpose -- and the single-instance
  # B1_DIAGNOSTIC constraint binds ONLY the shadow/live-compare mode. So this
  # is deliberately the PRODUCTION shape, not the live-arm shape: same runtime
  # geometry, same exact4 pins, same refusal of diagnostic mode. The one thing
  # that differs is the qualifying evidence -- a Tier-B credential instead of a
  # byte gate -- which is verified in the container, tied to the attestation
  # export.
  # SPELLING (runner's dry-read, before this ever booted). The workload-keyed
  # gate below used to read FR13_FA2_QROW32_B1_EXACT4_*, so under
  # TIERB_WORKLOAD=exact16 the variable named EXACT4 had to contain SIXTEEN
  # ids -- correct, self-contradictory to read, and the obvious operator
  # mistake (leaving the four exact4 ids in a variable named exact4) refused
  # with a message about ids that said nothing about the naming.
  #
  # The tier-B route now has its own spelling. The old one is still accepted
  # because banked vehicles set it (promotion_ab_arm*.sh, the k0 live gate
  # runner, the gqa-pair timing runner), and the production and live-A/B gates
  # still read it on their own account -- this alias is tier-B only.
  #
  # When BOTH are present they must AGREE. An alias that silently prefers one
  # spelling is a second way to declare a workload, and two declarations that
  # can disagree is the shape of every mislabelled artifact in this campaign.
  if [[ -n "$FR13_FA2_QROW32_B1_TIERB_TASK_IDS" \
        && -n "$FR13_FA2_QROW32_B1_EXACT4_TASK_IDS" \
        && "$FR13_FA2_QROW32_B1_TIERB_TASK_IDS" != "$FR13_FA2_QROW32_B1_EXACT4_TASK_IDS" ]]; then
    echo "FR13 qrow32 B1 tier-b serve: FR13_FA2_QROW32_B1_TIERB_TASK_IDS and the legacy" \
         "FR13_FA2_QROW32_B1_EXACT4_TASK_IDS are both set and disagree; set one" >&2
    exit 2
  fi
  if [[ -n "$FR13_FA2_QROW32_B1_TIERB_SUBSET_SHA256" \
        && -n "$FR13_FA2_QROW32_B1_EXACT4_SUBSET_SHA256" \
        && "$FR13_FA2_QROW32_B1_TIERB_SUBSET_SHA256" != "$FR13_FA2_QROW32_B1_EXACT4_SUBSET_SHA256" ]]; then
    echo "FR13 qrow32 B1 tier-b serve: FR13_FA2_QROW32_B1_TIERB_SUBSET_SHA256 and the legacy" \
         "FR13_FA2_QROW32_B1_EXACT4_SUBSET_SHA256 are both set and disagree; set one" >&2
    exit 2
  fi
  _fr13_tierb_declared_ids=${FR13_FA2_QROW32_B1_TIERB_TASK_IDS:-$FR13_FA2_QROW32_B1_EXACT4_TASK_IDS}
  _fr13_tierb_declared_sha=${FR13_FA2_QROW32_B1_TIERB_SUBSET_SHA256:-$FR13_FA2_QROW32_B1_EXACT4_SUBSET_SHA256}
  _fr13_b1_tierb_workload_pins "$FR13_FA2_QROW32_B1_TIERB_WORKLOAD" || exit 2
  [[ "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
     && "${ENFORCE_EAGER:-0}" == "0" \
     && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" \
     && "$_fr13_tierb_declared_ids" == "$_fr13_tierb_task_ids" \
     && "$_fr13_tierb_declared_sha" == "$_fr13_tierb_subset_sha256" ]] || {
    echo "FR13 qrow32 B1 tier-b serve requires the FULL-graph identity of its DECLARED workload" \
         "FR13_FA2_QROW32_B1_TIERB_WORKLOAD=$FR13_FA2_QROW32_B1_TIERB_WORKLOAD" \
         "(expected task ids '$_fr13_tierb_task_ids' sha '$_fr13_tierb_subset_sha256')" >&2
    exit 2
  }
  echo "[fr13] B1 tier-b serve workload=$FR13_FA2_QROW32_B1_TIERB_WORKLOAD" \
       "subset=${_fr13_tierb_subset_file:-<none: synthetic shape, no SWE subset>}" >&2
  # THE CREDENTIAL PATH, SETTLED BY MEASUREMENT (2026-08-19). The host check
  # below and the in-container verify-tier-b consume the same file from two
  # different filesystems. Measured with the launcher's own mounts: the repo is
  # mounted at /workspace, so a host path like
  # /home/mark/shared/<repo>/results/... is NOT visible inside the container --
  # /home exists there but is the image's own, and the file is absent. One
  # variable therefore cannot serve both, which is why the campaign already has
  # the _HOST/container pattern; this adopts it.
  #
  # _HOST is what the operator supplies. The launcher verifies it, stages it
  # into the log directory that IS mounted, and derives the container path
  # itself -- so the two can never be supplied out of sync, and the container
  # sees an immutable snapshot whose digest is re-checked on the far side.
  [[ -f "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" \
     && ! -L "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" \
     && "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_SHA256" =~ ^[0-9a-f]{64}$ \
     && "$(sha256sum "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" | cut -d' ' -f1)" == "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_SHA256" ]] || {
    echo "FR13 qrow32 B1 tier-b serve requires its bound qualification credential at FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" >&2
    exit 2
  }
  cp -- "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_HOST" \
        "$LOG_DIR/fr13_fa2_qrow32_b1_tier_b_credential.json" || {
    echo "FR13 qrow32 B1 tier-b credential could not be staged into the log dir" >&2
    exit 2
  }
  [[ "$(sha256sum "$LOG_DIR/fr13_fa2_qrow32_b1_tier_b_credential.json" | cut -d' ' -f1)" \
     == "$FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL_SHA256" ]] || {
    echo "FR13 qrow32 B1 tier-b credential changed while being staged" >&2
    exit 2
  }
  FR13_FA2_QROW32_B1_TIER_B_CREDENTIAL=/logs/fr13_fa2_qrow32_b1_tier_b_credential.json
fi
if [[ -n "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" ]]; then
  # The runtime shape and the exact4 identity are required for every production
  # arm; only the shape of the qualifying evidence differs between them.
  [[ "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
     && "${ENFORCE_EAGER:-0}" == "0" \
     && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" \
     && "$FR13_FA2_QROW32_B1_EXACT4_TASK_IDS" == "astropy__astropy-12907,astropy__astropy-13033,astropy__astropy-13236,astropy__astropy-13398" \
     && "$FR13_FA2_QROW32_B1_EXACT4_SUBSET_SHA256" == "0e37b7137115332372ef76ba7c8db0db4a46ebad5db777c5b999bf797ae853f5" ]] || {
    echo "FR13 qrow32 B1 production requires the canonical exact4 FULL-graph identity" >&2
    exit 2
  }
  if [[ "$FR13_FA2_QROW32_B1_PRODUCTION_ARM" == "gqa_pair" ]]; then
    # The GQA-pair arm is credentialed from the sealed byte gate plus the live
    # A/B result that gate binds by digest. Both arrive by path and are checked
    # here; the credential itself re-derives the whole chain at issue time.
    [[ -f "$FR13_FA2_QROW32_B1_GQA_PAIR_GATE_JSON" \
       && ! -L "$FR13_FA2_QROW32_B1_GQA_PAIR_GATE_JSON" \
       && -f "$FR13_FA2_QROW32_B1_GQA_PAIR_LIVE_RESULT_JSON" \
       && ! -L "$FR13_FA2_QROW32_B1_GQA_PAIR_LIVE_RESULT_JSON" \
       && "$FR13_FA2_QROW32_B1_GQA_PAIR_GATE_SHA256" =~ ^[0-9a-f]{64}$ \
       && "$(sha256sum "$FR13_FA2_QROW32_B1_GQA_PAIR_GATE_JSON" | cut -d' ' -f1)" == "$FR13_FA2_QROW32_B1_GQA_PAIR_GATE_SHA256" ]] || {
      echo "FR13 qrow32 B1 GQA-pair production requires its sealed byte gate and bound live result" >&2
      exit 2
    }
  else
    [[ -f "$FR13_FA2_QROW32_B1_LIVE_PASS_JSON" \
       && ! -L "$FR13_FA2_QROW32_B1_LIVE_PASS_JSON" \
       && "$FR13_FA2_QROW32_B1_LIVE_PASS_SHA256" =~ ^[0-9a-f]{64}$ ]] || {
      echo "FR13 qrow32 B1 production requires its arm-bound PASS" >&2
      exit 2
    }
  fi
fi
if [[ "$FR13_FA2_QROW16_LIVE_PAGED_AB" == "1" ]]; then
  [[ "$FR13_FA2_QROW16_LIVE_PAGED_AB_INSTANCE_ID" == "astropy__astropy-12907" \
     && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "1" \
     && "$FR13_DRAFT_VOCAB_ROOT" == "1" \
     && "${FR13_DRAFT_VOCAB_K:-65536}" == "65536" \
     && "${FR13_DRAFT_VOCAB_BLOCKS:-}" == "/workspace/scripts/fr13_dvk_subset_blocks.json" \
     && -z "${FR13_NEEDS_ALLOW:-}" \
     && "$FR13_FIXED32_TAW_NATIVE_PRECOMPUTE" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB:-0}" == "0" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_CANDIDATE:-}" \
     && "${FR13_FIXED32_SFWD_STATE_FUSION_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_CUTLASS_WAVE:-stock}" == "stock" \
     && "${FR13_DFWD_UNIFIED_BM8_LIVE_AB:-0}" == "0" \
     && "${FR13_DRAFT_HEAD_PAD_ROWS:-0}" == "0" \
     && "${FR13_DRAFT_HEAD_PAD_ALL_BYTE_AB:-0}" == "0" \
     && "${FR13_DRAFT_HEAD_M32_LIVE_AB:-0}" == "0" \
     && -z "${FR13_FIXED32_GDN_PATH_BV_CANDIDATE:-}" ]] || {
    echo "FR13 qrow16 live A/B requires the canonical K64 ROOT=1 real B1 task and no other candidate" >&2
    exit 2
  }
fi
if [[ "$FR13_FA2_QROW16_PRODUCTION" == "1" ]]; then
  [[ -f "$FR13_FA2_QROW16_LIVE_PASS_JSON" \
     && ! -L "$FR13_FA2_QROW16_LIVE_PASS_JSON" \
     && "$FR13_FA2_QROW16_LIVE_PASS_SHA256" =~ ^[0-9a-f]{64}$ ]] || {
    echo "FR13 qrow16 production requires a regular live PASS JSON and its SHA-256" >&2
    exit 2
  }
fi
case "$FR13_FIXED32_CUTLASS_WAVE" in
  stock|streamk_coop128|streamk_coop128_byte_ab|streamk_force_wide256|streamk_force_wide256_byte_ab|static_persistent_stocktile|static_persistent_stocktile_byte_ab|divisor_static_stocktile|divisor_static_stocktile_byte_ab|identity_stage2_static|identity_stage2_static_byte_ab|identity_stage2_pingpong_b1|identity_stage2_pingpong_b1_byte_ab|identity_onen_b1|identity_onen_b1_byte_ab|identity_onen_n5120_single_b1|identity_onen_n5120_single_b1_byte_ab|identity_onen_n5120_fullgrid_b1|identity_onen_n5120_fullgrid_b1_byte_ab|identity_wide256_fullgrid_b1|identity_wide256_fullgrid_b1_byte_ab|identity_stockshape_b4|identity_stockshape_b4_byte_ab|identity_stockshape_stage2_b4|identity_stockshape_stage2_b4_byte_ab|identity_twom_b4|identity_twom_b4_byte_ab|identity_hybrid_n5120_b4|identity_hybrid_n5120_b4_byte_ab|identity_divisor_b4|identity_divisor_b4_byte_ab|persistent_b4_m128|persistent_b4_m128_byte_ab|persistent_b4_m128_static|persistent_b4_m128_static_byte_ab) ;;
  *)
    echo "FR13_FIXED32_CUTLASS_WAVE has an unsupported selector" >&2
    exit 2
    ;;
esac
case "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" in
  0|1) ;;
  *) echo "FR13_FIXED32_B1_DIAGNOSTIC must be exactly 0 or 1" >&2; exit 2 ;;
esac
case "$FR13_FIXED32_CUTLASS_WAVE_PRODUCTION" in
  0|1) ;;
  *) echo "FR13_FIXED32_CUTLASS_WAVE_PRODUCTION must be 0 or 1" >&2; exit 2 ;;
esac
if [[ -n "${FR13_FIXED32_CUTLASS_WAVE_PRODUCTION_PASS_SIDECAR:-}" \
      || -n "${FR13_FIXED32_CUTLASS_WAVE_PRODUCTION_PASS_SIDECAR_SHA256:-}" ]]; then
  echo "CUTLASS Stream-K internal production credentials are launcher-private" >&2
  exit 2
fi
case "$FR13_DFWD_UNIFIED_BM8_LIVE_AB" in
  0|1) ;;
  *) echo "FR13_DFWD_UNIFIED_BM8_LIVE_AB must be 0 or 1" >&2; exit 2 ;;
esac
case "$FR13_DFWD_UNIFIED_BM8_PRODUCTION" in
  0|1) ;;
  *) echo "FR13_DFWD_UNIFIED_BM8_PRODUCTION must be 0 or 1" >&2; exit 2 ;;
esac
if [[ "$FR13_DFWD_UNIFIED_BM8_PRODUCTION" == "1" \
      && "$FR13_FIXED32_CUTLASS_WAVE" != "stock" ]]; then
  echo "FR13 DFWD unified BM8 production requires the stock CUTLASS wave" >&2
  exit 2
fi
if [[ "$FR13_FIXED32_CUTLASS_WAVE" != "stock" \
      && ( "$FR13_DFWD_UNIFIED_BM8_LIVE_AB" != "0" \
           || "$FR13_DFWD_UNIFIED_BM8_PRODUCTION" != "0" ) ]]; then
  echo "nonstock CUTLASS wave requires both BM8 selectors to be 0" >&2
  exit 2
fi
case "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE" in
  0|byte_ab|1) ;;
  *) echo "FR13_FIXED32_B1_FP8_QUANT_REGCACHE must be 0, byte_ab, or 1" >&2; exit 2 ;;
esac
# ---------------------------------------------------------------------------
# FR14 FP8-LEVER REFUSAL (2026-08-16)
#
# The whole fp8 GEMM lever portfolio targets vLLM's w8a8 BLOCKWISE-FP8
# dispatcher: OPT-A / FR13_GB10_FP8_GEMV_CFG (whose guard requires
# weight_block_size == [128,128] -- fr10_phase4_patch_vllm_tree_gdn.py:35582),
# FR13_FIXED32_B1_FP8_QUANT_REGCACHE (per_token_group_quant.cu), and every
# non-'stock' FR13_FIXED32_CUTLASS_WAVE variant
# (scaled_mm_blockwise_sm120_fp8.cu). Under a non-fp8 checkpoint that
# dispatcher is simply off-path.
#
# They do not crash -- which is WORSE. An arm named cat9-opta boots, passes
# every flag assertion, writes a full evidence bundle, and measures NOTHING;
# the result would then be quoted as a lever verdict. Refuse instead.
#
# The levers are NOT deleted: re-point them at the nvfp4 dispatch site
# (nvfp4_scaled_mm_sm120_kernels.cu) or serve an fp8 checkpoint, and they arm
# again with no further change here.
_fr14_quant_probe='
import json, sys
try:
    cfg = json.load(open(sys.argv[1], encoding="utf-8"))
except Exception:
    print("")
    raise SystemExit(0)
quant = cfg.get("quantization_config")
print(quant.get("quant_method", "") if isinstance(quant, dict) else "")
'
_fr14_served_quant_method=$(
  python3 -c "$_fr14_quant_probe" "$SERVED_MODEL_PATH/config.json" 2>/dev/null
) || _fr14_served_quant_method=""
_fr14_armed_fp8_levers=()
if [[ "${FR13_GB10_FP8_GEMV_CFG:-0}" != "0" ]]; then
  _fr14_armed_fp8_levers+=("FR13_GB10_FP8_GEMV_CFG=${FR13_GB10_FP8_GEMV_CFG}")
fi
if [[ "${FR13_FIXED32_B1_FP8_QUANT_REGCACHE:-0}" != "0" ]]; then
  _fr14_armed_fp8_levers+=("FR13_FIXED32_B1_FP8_QUANT_REGCACHE=${FR13_FIXED32_B1_FP8_QUANT_REGCACHE}")
fi
if [[ -n "${FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO:-}" ]]; then
  _fr14_armed_fp8_levers+=("FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO=${FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO}")
fi
if [[ "${FR13_FIXED32_CUTLASS_WAVE:-stock}" != "stock" ]]; then
  _fr14_armed_fp8_levers+=("FR13_FIXED32_CUTLASS_WAVE=${FR13_FIXED32_CUTLASS_WAVE}")
fi
if [[ -n "${FR13_FIXED32_CUTLASS_WAVE_SO:-}" ]]; then
  _fr14_armed_fp8_levers+=("FR13_FIXED32_CUTLASS_WAVE_SO=${FR13_FIXED32_CUTLASS_WAVE_SO}")
fi
if (( ${#_fr14_armed_fp8_levers[@]} > 0 )) && [[ "$_fr14_served_quant_method" != "fp8" ]]; then
  echo "FR14 REFUSAL: fp8-only GEMM lever(s) armed against a non-fp8 checkpoint." >&2
  echo "  served checkpoint : $SERVED_MODEL_PATH" >&2
  echo "  quant_method      : ${_fr14_served_quant_method:-<absent>} (required: fp8)" >&2
  printf '  armed lever       : %s\n' "${_fr14_armed_fp8_levers[@]}" >&2
  echo "  These levers target the w8a8 blockwise-fp8 dispatcher, which this" >&2
  echo "  checkpoint never enters. They would boot, assert clean and measure" >&2
  echo "  nothing. Disarm them, or re-target them at the nvfp4 dispatch site." >&2
  exit 2
fi
unset _fr14_served_quant_method _fr14_armed_fp8_levers _fr14_quant_probe
# ---------------------------------------------------------------------------
FR13_FP8_QUANT_REGCACHE_DOCKER_ARGS=()
if [[ -n "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" ]]; then
  [[ "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" == /* \
     && "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" != *:* \
     && -f "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" \
     && ! -L "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" \
     && "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO_SHA256" =~ ^[0-9a-f]{64}$ \
     && "$(sha256sum "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" | awk '{print $1}')" == "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO_SHA256" ]] || {
    echo "FP8 quant regcache requires a pinned absolute candidate binary" >&2
    exit 2
  }
  [[ "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" \
     && "$MAX_NUM_SEQS" == "1" \
     && "$FR13_DRAFT_VOCAB_ROOT" == "1" \
     && "${FR13_DRAFT_VOCAB_K:-}" == "65536" \
     && "$FR13_FIXED32_CUTLASS_WAVE" == "stock" \
     && -z "$FR13_FIXED32_CUTLASS_WAVE_SO" ]] || {
    echo "FP8 quant regcache binary requires isolated Hydra27 physical32 K64/root1 B1" >&2
    exit 2
  }
  .venv/bin/python scripts/fr13_fp8_quant_regcache_runtime.py verify-binary \
    "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" \
    --expected-sha256 "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO_SHA256" \
    >/dev/null
  FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO=$(
    realpath "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO"
  )
  FR13_FP8_QUANT_REGCACHE_DOCKER_ARGS=(
    -v "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO:/tmp/fr13_fp8_quant_regcache.abi3.so:ro"
  )
  if [[ "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE" == "byte_ab" ]]; then
    [[ "$FR13_FIXED32_B1_DIAGNOSTIC" == "1" \
       && "${ENFORCE_EAGER:-0}" == "1" \
       && -z "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
       && -z "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_SHA256" ]] || {
      echo "FP8 quant byte A/B requires eager real-B1 diagnostic mode and no PASS" >&2
      exit 2
    }
  elif [[ "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE" == "1" ]]; then
    [[ "$FR13_FIXED32_B1_DIAGNOSTIC" == "0" \
       && "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" == /* \
       && -f "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
       && ! -L "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
       && "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_SHA256" =~ ^[0-9a-f]{64}$ ]] || {
      echo "FP8 quant production requires a pinned real-B1 PASS sidecar" >&2
      exit 2
    }
    .venv/bin/python scripts/fr13_fp8_quant_regcache_pass.py verify \
      --sidecar "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
      --expected-sidecar-sha256 "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_SHA256" \
      --candidate-so "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" \
      --expected-candidate-sha256 "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO_SHA256" \
      --patch-source scripts/fr13_patch_fp8_quant_fixed32.py \
      >/dev/null
    FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON=$(
      realpath "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON"
    )
    FR13_FP8_QUANT_REGCACHE_DOCKER_ARGS+=(
      -v "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON:/tmp/fr13_fp8_quant_regcache.pass.json:ro"
    )
  else
    [[ -z "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
       && -z "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_SHA256" ]] || {
      echo "FP8 quant stock-control binary forbids a production PASS" >&2
      exit 2
    }
  fi
elif [[ "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE" != "0" \
        || -n "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO_SHA256" \
        || -n "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
        || -n "$FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_SHA256" ]]; then
  echo "FP8 quant regcache selector or credentials have no candidate binary" >&2
  exit 2
fi
FR13_CUTLASS_WAVE_DOCKER_ARGS=()
if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "stock" ]]; then
  [[ -z "$FR13_FIXED32_CUTLASS_WAVE_SO" \
     && -z "$FR13_FIXED32_CUTLASS_WAVE_RESOURCE_CREDENTIAL" \
     && -z "$FR13_FIXED32_CUTLASS_WAVE_RESOURCE_CREDENTIAL_SHA256" \
     && "$FR13_FIXED32_CUTLASS_WAVE_PRODUCTION" == "0" \
     && -z "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_SHA256" \
     && -z "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_SHA256" \
     && -z "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_SHA256" \
     && -z "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256" \
     && -z "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256" \
     && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256" \
     && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256" \
     && -z "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT" ]] || {
    echo "stock CUTLASS wave selector forbids candidate binary and production credentials" >&2
    exit 2
  }
else
  _fr13_cutlass_b4=0
  if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_divisor_b4" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_divisor_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_b4" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_stage2_b4" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_stage2_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_twom_b4" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_twom_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_hybrid_n5120_b4" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_hybrid_n5120_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_static" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_static_byte_ab" ]]; then
    _fr13_cutlass_b4=1
  fi
  if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_static" ]]; then
    echo "CUTLASS static M128 production remains unavailable until Tail23 and Hydra27 raw-byte PASS" >&2
    exit 2
  fi
  if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_b4" ]]; then
    echo "CUTLASS B4 stock-shape identity production remains unavailable until Tail23 and Hydra27 raw-byte PASS" >&2
    exit 2
  fi
  if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_divisor_b4" ]]; then
    echo "CUTLASS B4 divisor identity production remains unavailable until Tail23 and Hydra27 raw-byte PASS" >&2
    exit 2
  fi
  if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "static_persistent_stocktile" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "divisor_static_stocktile" ]]; then
    echo "CUTLASS static B1 production remains unavailable until the K64/root raw-byte PASS" >&2
    exit 2
