    exit 2
    ;;
esac
# A CONTROL ARM SERVES THE INCUMBENT AND NOTHING ELSE. If this flag could sit
# beside a serving selector it would stop being a control and become an
# unlabelled second treatment, so every selector that can change the served
# kernel is refused here. That is also what keeps the flag honest as "metrics
# classification only": there is no configuration in which it accompanies a
# candidate.
if [[ "$_fr13_gdn_single_launch_timing_control" == "1" ]]; then
  [[ -n "${FR13_FIXED32_MODE:-}" \
     && "$_fr13_gdn_single_launch_production" == "0" \
     && "$_fr13_gdn_gqa_group3_production" == "0" \
     && -z "$_fr13_gdn_single_launch_production_batch" \
     && -z "$_fr13_gdn_single_launch_pass_json" \
     && -z "$_fr13_gdn_path_bv_candidate" \
     && -z "$_fr13_gdn_path_bv_production" \
     && -z "$_fr13_gdn_single_launch_expected_batch" \
     && "${FR13_FIXED32_GDN_SINGLE_LAUNCH_TREE:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_PRODUCTION:-0}" == "0" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_CANDIDATE:-}" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_PRODUCTION:-}" ]] || {
    echo "FR13 GDN single-launch timing control must serve the incumbent alone" >&2
    exit 2
  }
fi
if [[ -n "$_fr13_gdn_path_bv_candidate" ]]; then
  [[ -n "${FR13_FIXED32_MODE:-}" ]] || {
    echo "FR13_FIXED32_GDN_PATH_BV_CANDIDATE requires FR13_FIXED32_MODE" >&2
    exit 2
  }
  [[ "$_fr13_gdn_path_bv_candidate" == "16" \
     || "$_fr13_gdn_path_bv_candidate" == "32" \
     || "$_fr13_gdn_path_bv_candidate" == "64" \
	     || "$_fr13_gdn_path_bv_candidate" == "128" \
	     || "$_fr13_gdn_path_bv_candidate" == "single_launch" \
	     || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
	     || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" ]] || {
	    echo "FR13_FIXED32_GDN_PATH_BV_CANDIDATE must be exactly 16, 32, 64, 128, single_launch, gqa_group3, or gqa_group3_bv16" >&2
	    exit 2
	  }
	  # FR14 ARM B: profile-aware (see _fr13_assert_draft_vocab_profile). Was
	  # `K != 65536 || ROOT != 1`, which pinned this gate to the K64 era and
	  # would refuse the promoted K0 config arm B's profile chain runs on.
	  if [[ "$_fr13_gdn_path_bv_candidate" == "single_launch" \
	        || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
	        || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" ]]; then
	    _fr13_assert_draft_vocab_profile \
	      "$FR13_FIXED32_GDN_LIVE_GATE_QUALIFICATION_PROFILE" \
	      "FR13 ordered GDN live gate" || exit 2
	  fi
	  if [[ ( "$_fr13_gdn_path_bv_candidate" == "single_launch" \
	          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
	          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" ) \
	        && ( ! ( "$_fr13_gdn_single_launch_expected_batch" == "1" \
                 || "$_fr13_gdn_single_launch_expected_batch" == "4" ) \
             || "$MAX_NUM_SEQS" != "$_fr13_gdn_single_launch_expected_batch" \
             || "${SWE_CONCURRENCY:-}" != "$_fr13_gdn_single_launch_expected_batch" ) ]]; then
	    echo "FR13 ordered GDN gate requires one baked expected batch matching process capacity and concurrency" >&2
	    exit 2
	  fi
	  if [[ ( "$_fr13_gdn_path_bv_candidate" == "single_launch" \
	          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
	          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" ) \
	        && ( "$FR10_METRICS" != "1" \
             || "${FR13_RING_EXPORT:-1}" != "1" \
             || "${FR13_FLAGS_INKERNEL:-1}" != "1" \
             || "${ENFORCE_EAGER:-0}" != "0" \
             || "${CUDAGRAPH_MODE:-}" != "FULL_AND_PIECEWISE" \
             || ! ( "$MAX_NUM_SEQS" == "1" \
                     || "$MAX_NUM_SEQS" == "4" ) \
             || "${SWE_CONCURRENCY:-}" != "$MAX_NUM_SEQS" ) ]]; then
	    echo "FR13 ordered GDN live gate requires exact B1/B4 FULL-graph metrics/ring/flags contract" >&2
	    exit 2
	  fi
	fi
	if [[ "$_fr13_gdn_path_bv_candidate" != "single_launch" \
	      && "$_fr13_gdn_path_bv_candidate" != "gqa_group3" \
	      && "$_fr13_gdn_path_bv_candidate" != "gqa_group3_bv16" \
	      && -n "$_fr13_gdn_single_launch_expected_batch" ]]; then
	  echo "FR13 GDN ordered expected batch is set without its candidate" >&2
  exit 2
fi
if [[ -n "$_fr13_gdn_path_bv_production" ]]; then
  [[ -n "${FR13_FIXED32_MODE:-}" ]] || {
    echo "FR13_FIXED32_GDN_PATH_BV_PRODUCTION requires FR13_FIXED32_MODE" >&2
    exit 2
  }
  [[ "$_fr13_gdn_path_bv_production" == "16" \
     || "$_fr13_gdn_path_bv_production" == "32" \
     || "$_fr13_gdn_path_bv_production" == "64" \
     || "$_fr13_gdn_path_bv_production" == "128" ]] || {
    echo "FR13_FIXED32_GDN_PATH_BV_PRODUCTION must be exactly 16, 32, 64, or 128" >&2
    exit 2
  }
  [[ -f "$_fr13_gdn_path_bv_pass_json" \
     && ! -L "$_fr13_gdn_path_bv_pass_json" ]] || {
