elif [[ -n "$_fr13_gdn_gqa_group3_production_batch" \
        || -n "$_fr13_gdn_gqa_group3_pass_json" ]]; then
  echo "FR13 GDN GQA-group3 production batch/PASS is set without its arm" >&2
  exit 2
fi
# ---- GDN SINGLE-LAUNCH PRODUCTION ARM (built 2026-08-14, default OFF) ----
# The folded GDN scan kernel fixed32_gdn_single_launch_tree_v2 issues ONE physical
# launch per layer for the whole batch where the deployed reference issues two per
# request-layer, and in doing so deletes the L0->L1 handoff outright: the
# engagement needle below demands state_export_writes == 0 and
# state_parent_reads == 0, which is the structural signature of the fold and
# cannot be faked by a kernel that merely runs fast.
#
# fr13_canonical_env.sh owns the VALUE and ships it as 0, because this arm is
# byte-LEGAL but not SEALED: the b4 Hydra27 live gate returned PASS over 1,584
# records at request-tuple width 4, and the b=4 cost probe priced the fold at
# 8.984 ms/step, but no sealing campaign has bounded the gain. Everything in this
# block is therefore machinery for a promotion that has not happened yet -- which
# is the point. It is built, guarded and exercised now so that the eventual flip
# is a one-token change to the registry and not a scramble to invent the guards
# under time pressure, and so the mandatory re-gate exercises the production
# shape rather than a shape that only exists on paper.
#
# The default is applied HERE, not in the registry, and only where the selector is
# legal AND unambiguous -- the same three-part test the FA2 B4 promotion uses:
#   * the caller did not NAME the arm (naming it 0 is a deliberate opt-out and is
#     obeyed -- it is how a campaign arm says "serve the incumbent");
#   * fixed32 at a batch that matches process capacity AND client concurrency, not
#     the B1 diagnostic shape;
#   * the launch PRESENTED a gate credential. This is the clause that keeps the
#     promotion honest for the same reason it does for FA2: B=4/concurrency 4
#     fixed32 is the shape of the ENTIRE campaign -- every floor gate, timing pair
#     and live gate in this tree runs it -- so keying on batch alone would hand a
#     credentialed selector to every one of them and the credential chain would
#     then have to refuse them all at boot. Holding the credential is what
#     distinguishes a production serve from a campaign arm.
#   * no sibling GDN selector is engaged. The patched GDN call site hosts exactly
#     one candidate, so the refusals below stay reachable rather than being
#     resolved first-one-wins.
if (( _FR13_FIXED32_GDN_SINGLE_LAUNCH_PRODUCTION_NAMED == 0 )) \
   && [[ ( "${FR13_FIXED32_MODE:-}" == "tail6_fixed32" \
           || "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" ) \
         && ( "$MAX_NUM_SEQS" == "1" || "$MAX_NUM_SEQS" == "4" ) \
         && "${SWE_CONCURRENCY:-}" == "$MAX_NUM_SEQS" \
         && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
         && -n "$_fr13_gdn_single_launch_pass_json" \
         && "$_fr13_gdn_gqa_group3_production" == "0" \
         && "${FR13_FIXED32_GDN_SINGLE_LAUNCH_TREE:-0}" == "0" \
         && -z "$_fr13_gdn_single_launch_expected_batch" \
         && -z "$_fr13_gdn_path_bv_candidate" \
         && -z "$_fr13_gdn_path_bv_production" ]]; then
  _fr13_gdn_single_launch_production=${FR13_FIXED32_GDN_SINGLE_LAUNCH_PRODUCTION_DEFAULT:-0}
  if [[ "$_fr13_gdn_single_launch_production" != "0" \
        && "$_fr13_gdn_single_launch_production" != "1" ]]; then
    echo "FR13_FIXED32_GDN_SINGLE_LAUNCH_PRODUCTION_DEFAULT must be exactly 0 or 1" >&2
    exit 2
  fi
  if [[ "$_fr13_gdn_single_launch_production" == "1" ]]; then
    _fr13_gdn_single_launch_production_batch=${_fr13_gdn_single_launch_production_batch:-$MAX_NUM_SEQS}
    echo "[fr13] GDN single-launch production arm unnamed; serving the promoted default" \
         "FR13_FIXED32_GDN_SINGLE_LAUNCH_PRODUCTION=$_fr13_gdn_single_launch_production" >&2
  fi
fi
if [[ "$_fr13_gdn_single_launch_production" == "1" ]]; then
  _fr13_assert_draft_vocab_profile \
    "$FR13_FIXED32_GDN_SINGLE_LAUNCH_QUALIFICATION_PROFILE" "FR13 GDN single-launch production" || exit 2
  [[ -n "${FR13_FIXED32_MODE:-}" \
     && ( "$_fr13_gdn_single_launch_production_batch" == "1" \
          || "$_fr13_gdn_single_launch_production_batch" == "4" ) \
     && "$MAX_NUM_SEQS" == "$_fr13_gdn_single_launch_production_batch" \
     && "${SWE_CONCURRENCY:-}" == "$MAX_NUM_SEQS" \
     && "${FR13_TREE_GDN_GEOM_OVERRIDE:-}" == "BV=8" \
     && "${FR13_SCAN_ALIGN:-0}" == "0" \
     && "${FR13_NPAD_INVARIANT:-0}" == "0" \
     && "$FR10_METRICS" == "1" \
     && "${FR13_RING_EXPORT:-1}" == "1" \
     && "${FR13_FLAGS_INKERNEL:-1}" == "1" \
     && "${ENFORCE_EAGER:-0}" == "0" \
     && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" \
     && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
     && "$_fr13_gdn_gqa_group3_production" == "0" \
     && "${FR13_FIXED32_GDN_SINGLE_LAUNCH_TREE:-0}" == "0" \
     && -z "$_fr13_gdn_single_launch_expected_batch" \
     && -z "$_fr13_gdn_path_bv_candidate" \
     && -z "$_fr13_gdn_path_bv_production" \
     && "${FR13_FIXED32_BATCH_GDN_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_PRODUCTION:-0}" == "0" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_CANDIDATE:-}" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_PRODUCTION:-}" ]] || {
    echo "FR13 GDN single-launch production requires exact credentialed B1/B4 physical32 FULL-graph pins" >&2
    exit 2
  }
  [[ -f "$_fr13_gdn_single_launch_pass_json" \
     && ! -L "$_fr13_gdn_single_launch_pass_json" ]] || {
    echo "FR13 GDN single-launch production requires a regular live PASS JSON" >&2
    exit 2
  }
  _fr13_gdn_single_launch_source_commit=$(git rev-parse --verify 'HEAD^{commit}')
  [[ "$_fr13_gdn_single_launch_source_commit" =~ ^[0-9a-f]{40}$ ]] || {
    echo "FR13 GDN single-launch production cannot resolve exact source HEAD" >&2
    exit 2
  }
  .venv/bin/python \
    scripts/fr13_gdn_single_launch_production_credential.py \
    --credential "$_fr13_gdn_single_launch_pass_json" \
    --source-commit "$_fr13_gdn_single_launch_source_commit" \
    --profile fixed32 \
    --mode "$FR13_FIXED32_MODE" \
    --batch "$_fr13_gdn_single_launch_production_batch" \
    --draft-vocab-profile "$FR13_FIXED32_GDN_SINGLE_LAUNCH_QUALIFICATION_PROFILE"
elif [[ -n "$_fr13_gdn_single_launch_production_batch" \
        || -n "$_fr13_gdn_single_launch_pass_json" ]]; then
  echo "FR13 GDN single-launch production batch/PASS is set without its arm" >&2
  exit 2
fi
if [[ "$FR13_DRAFT_HEAD_M32_LIVE_AB" == "1" \
      || "$FR13_DRAFT_HEAD_M32_PRODUCTION" == "1" \
      || "$FR13_DRAFT_HEAD_M32_TIMING_ARM" == "1" ]]; then
  [[ "$FR13_FIXED32_TAW_NATIVE_PRECOMPUTE" == "0" \
     && "$FR13_FIXED32_TAW_NATIVE_PRECOMPUTE_PRODUCTION" == "0" \
     && "$FR13_FA2_QROW16_LIVE_PAGED_AB" == "0" \
     && "$FR13_FA2_QROW16_PRODUCTION" == "0" \
     && "$FR13_DFWD_UNIFIED_BM8_LIVE_AB" == "0" \
     && "$FR13_DFWD_UNIFIED_BM8_PRODUCTION" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_BYTE_AB:-0}" == "0" \
     && "${FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB:-0}" == "0" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_CANDIDATE:-}" \
     && "${FR13_FIXED32_BATCH_GDN_PRODUCTION:-0}" == "0" \
     && -z "${FR13_FIXED32_BATCH_GDN_BV_PRODUCTION:-}" \
     && -z "$_fr13_gdn_path_bv_candidate" \
     && -z "$_fr13_gdn_path_bv_production" \
     && "$FR13_FIXED32_CUTLASS_WAVE" == "stock" \
     && -z "$FR13_FIXED32_CUTLASS_WAVE_SO" \
     && "${FR13_FIXED32_ATTRIBUTION_ONLY:-0}" == "0" ]] || {
    echo "FR13 draft-head M32 must be the only kernel candidate in its arm" >&2
    exit 2
  }
fi
_fr13_fixed32_expected_gdn_geom="BV=8"
if [[ -n "$_fr13_gdn_path_bv_production" ]]; then
  _fr13_fixed32_expected_gdn_geom="BV=$_fr13_gdn_path_bv_production"
fi

# Fixed-32 is a closed execution bucket, not a generic <=32-node tree. Validate
# the topology/mask tuple and all route pins before patching or allocating GPU
# memory so an inherited legacy/fallback flag cannot produce evidence.
if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  [[ "$MAX_NUM_SEQS" =~ ^[1-4]$ ]] \
    || { echo "fixed32 requires MAX_NUM_SEQS in [1,4], got $MAX_NUM_SEQS" >&2; exit 2; }
  TREE="$TREE" \
  SPEC_CONFIG="$SPEC_CONFIG" \
  FR13_FIXED32_MODE="$FR13_FIXED32_MODE" \
  FR13_FIXED32_VALID_MASK="${FR13_FIXED32_VALID_MASK:-}" \
  FR13_FIXED32_ACTIVE_NODES="${FR13_FIXED32_ACTIVE_NODES:-}" \
  FR13_FIXED32_PHYSICAL_DRAFTS="${FR13_FIXED32_PHYSICAL_DRAFTS:-}" \
  FR13_FIXED32_TAW_WALK_CAP="${FR13_FIXED32_TAW_WALK_CAP:-}" \
  NUM_SPECULATIVE_TOKENS="$NUM_SPECULATIVE_TOKENS" \
    .venv/bin/python - <<'PY'
import ast
import json
import os
import sys

sys.path.insert(0, "scripts")
import fr13_fixed32_topology as topology

topology.validate_contract()
topology.validate_gate_contract()
topology.validate_tail10_contract()
mode = os.environ["FR13_FIXED32_MODE"]
# PROFILE-AWARE. Three things in this block vary by profile, not one: the
# mask/nodes table, the TREE this mode's paths must equal, and the walk cap.
# tail6 and hydra27 share one physical tree and differ only in mask; hydra31 is
# a DIFFERENT tree (14 of 31 draft ids carry different paths, ancestry
# 90873d81 -> 5b33c46a), so keying only the table would move the refusal three
# lines down to the TREE comparison, and then again to the walk cap.
_shape_of = {
    "tail6_fixed32": topology.PROFILE_HYDRA27,
    "hydra27_fixed32": topology.PROFILE_HYDRA27,
    "hydra31_fixed32": topology.PROFILE_HYDRA31,
}
expected = {
    "tail6_fixed32": (
        topology.TAIL6_VALID_MASK,
        topology.TAIL6_ACTIVE_DRAFTS,
    ),
    "hydra27_fixed32": (
        topology.HYDRA27_VALID_MASK,
        topology.HYDRA27_ACTIVE_DRAFTS,
    ),
    "hydra31_fixed32": (
        topology.HYDRA31_VALID_MASK,
        topology.HYDRA31_ACTIVE_DRAFTS,
    ),
}
if mode not in expected or mode not in _shape_of:
    raise SystemExit(f"unsupported fixed32 mode: {mode!r}")
_profile = topology.profile(_shape_of[mode])
tree = tuple(tuple(path) for path in ast.literal_eval(os.environ["TREE"]))
if tree != tuple(_profile["choices"]):
    raise SystemExit(f"fixed32 TREE differs from the {mode} choices")
mask_text = os.environ["FR13_FIXED32_VALID_MASK"]
try:
    mask = int(mask_text, 0)
except ValueError as error:
    raise SystemExit(f"invalid fixed32 mask {mask_text!r}") from error
try:
    active = int(os.environ["FR13_FIXED32_ACTIVE_NODES"])
    physical_drafts = int(os.environ["FR13_FIXED32_PHYSICAL_DRAFTS"])
    walk_cap = int(os.environ["FR13_FIXED32_TAW_WALK_CAP"])
    spec_tokens = int(os.environ["NUM_SPECULATIVE_TOKENS"])
except ValueError as error:
    raise SystemExit("fixed32 integer route pin is malformed") from error
if (mask, active) != expected[mode]:
    raise SystemExit(
        f"fixed32 mode tuple mismatch: mode={mode} mask={mask:#x} active={active}"
    )
if (
    physical_drafts != topology.PHYSICAL_DRAFTS
    or walk_cap != int(_profile["walk_cap"])
    or spec_tokens != topology.PHYSICAL_DRAFTS
):
    raise SystemExit(
        "fixed32 shape mismatch: "
        f"physical_drafts={physical_drafts} walk_cap={walk_cap} "
        f"spec_tokens={spec_tokens}"
    )
config = json.loads(os.environ["SPEC_CONFIG"])
if config != {
    "method": "qwen3_5_mtp",
    "num_speculative_tokens": topology.PHYSICAL_DRAFTS,
    "speculative_token_tree": os.environ["TREE"],
}:
    raise SystemExit("fixed32 SPEC_CONFIG contains an alternate method/shape")
PY

  _fixed32_required_one=(
    FR13_FIXED32_WORK_CENSUS FR13_FIXED32_DEVICE_PUBLISH
    FR13_FIXED32_ACCEPT_PACK FR13_FIXED32_REQKEY_DEVICE
    FR13_FIXED32_KV_REMAP16 FR13_FIXED32_COMMIT_DEVICE_FILL
    FR13_DEVICE_MULTIDRAFT FR13_DRAFTER_GRAPH
    FR13_DRAFTER_SINGLE_LOGITS FR13_DM_DEPTHSYNC
    FR13_TAW FR13_PARENT_GATHER FR13_SUBTREE_PARALLEL FR13_EAGER_PACK
    FR13_COMMIT_BATCH_OUTPUT FR13_COMMITTER_NATIVE FR13_COMMITTER_BATCHED
    FR13_COMMITTER_GRAPH FR13_RING_EXPORT FR13_REPLAY_ROUTE
    FR13_ATTN_KV_REMAP FR13_SLOT_REORDER FR13_KV_REMAP_SYNCFREE
    FR13_FA2_TREE_BIAS FR13_TREE_CONV_FUSED FR13_CONV_WB_FUSED
    FR13_CONV_WB_BATCHED FR13_CONV_PREGATHER FR13_CONV_COMMITTED_PATH
    FR13_APC_COMMIT_TO_RUNNING_ROW FR13_TREE_RUNROW_INIT
    FR13_FLAGS_INKERNEL FR13_SFWD_GPU_TIMER FR13_DFWD_GPU_TIMER
    FR13_CFWD_GPU_TIMER FR13_TIMER_EXPLICIT_FLUSH
  )
  for _fixed32_pin in "${_fixed32_required_one[@]}"; do
    [[ "${!_fixed32_pin:-}" == "1" ]] \
      || { echo "fixed32 requires $_fixed32_pin=1" >&2; exit 2; }
  done
  case "${FR13_FIXED32_CONV_SOURCE_BATCH:-0}" in
    0|1) ;;
    *)
      echo "FR13_FIXED32_CONV_SOURCE_BATCH must be exactly 0 or 1" >&2
      exit 2
      ;;
  esac
  case "${FR13_FIXED32_CONV_COMMIT_ZERO_TAIL:-0}" in
    0|1) ;;
    *)
      echo "FR13_FIXED32_CONV_COMMIT_ZERO_TAIL must be exactly 0 or 1" >&2
      exit 2
      ;;
  esac
  case "${FR13_FIXED32_CONV_COMMIT_ZERO_TAIL_BYTE_AB:-0}" in
    0|1) ;;
    *)
      echo "FR13_FIXED32_CONV_COMMIT_ZERO_TAIL_BYTE_AB must be exactly 0 or 1" >&2
      exit 2
      ;;
  esac
  [[ "${FR13_FIXED32_CONV_COMMIT_ZERO_TAIL:-0}" == "0" \
     || "${FR13_FIXED32_CONV_COMMIT_ZERO_TAIL_BYTE_AB:-0}" == "0" ]] || {
    echo "zero-tail production and byte A/B are exclusive" >&2
    exit 2
  }
  if [[ "${FR13_FIXED32_CONV_COMMIT_ZERO_TAIL:-0}" == "1" ]]; then
    install -m 600 /dev/null \
      "$LOG_DIR/fr13_fixed32_conv_commit_zero_tail.arm"
  else
    rm -f "$LOG_DIR/fr13_fixed32_conv_commit_zero_tail.arm"
  fi
  _fixed32_required_zero=(
    FR13_MULTIDRAFT_GPU_TIMER FR13_REPLAY_GPU_TIMER
    FR13_COMMIT_FULL_GPU_TIMER FR13_COMMITTER_SG_TIMER
    FR13_REPLAY_ONLY_GPU_TIMER FR13_GRAPH_TIMER FR13_KVREMAP_TIMER
    FR13_STATEREMAP_TIMER FR13_DFWD_SPLIT_NEEDLE FR13_STEP_GRAPH
    FR13_COMMIT_OVERLAP FR13_REPLAY_MULTISTREAM
    FR13_BRANCH_ACCEPT_DIAG FR13_FORCE_SPINE_COMMIT
    FR13_FIX1_SELFCHECK FR13_COMMIT_ARGMAX_GATE
    FR13_FORK_MARGIN_DUMP FR13_CHASE_DIAG
    FR13_REPLAY_BOUNDARY_LOG FR13_GDN_SUBOP_MAB FR13_CONV_SUBOP_MAB
    FR13_FA2_MAB FR13_REPLAY_DURABLE_AB FR13_TREE_POSREAD_PROBE
    FR13_LEAK_PROBE FR13_SERVE_LOG FR13_TORCH_DET_WARN
    FR13_TCF_DIAG_OVERRIDE FR13_TCF_SELFCHECK
    FR13_SUBTREE_PARALLEL_SELFCHECK FR13_PARENT_GATHER_SELFCHECK
    FR13_TORCHPROF
    LUMO_FA_ACTIVATION_REPLAY_BATCH4_DIAG
    LUMO_FA_REPLAY_COMMIT_BATCH4_RUNNER_DIAG
    LUMO_IR_DIAGNOSTIC_UNISOLATED
    LUMO_IR_ALLOW_UNVERIFIED_SPINES2_MEASUREMENT
  )
  for _fixed32_pin in "${_fixed32_required_zero[@]}"; do
    [[ "${!_fixed32_pin:-0}" == "0" ]] \
      || { echo "fixed32 requires $_fixed32_pin=0" >&2; exit 2; }
  done
  case "${FR13_FIXED32_ATTRIBUTION_ONLY:-0}:${LUMO_NSYS_WRAP_VLLM:-0}:${FR13_FIXED32_NVTX_PROFILE:-0}" in
    0:0:0|1:1:1)
      ;;
    0:*)
      echo "fixed32 acceptance requires Nsight and NVTX profiling disabled" >&2
      exit 2
      ;;
    1:*)
      echo "fixed32 attribution requires Nsight and NVTX profiling enabled" >&2
      exit 2
      ;;
    *)
      echo "fixed32 attribution mode must be exactly 0 or 1" >&2
      exit 2
      ;;
  esac
  _fixed32_required_empty=(
    FR13_PREWARM_TRIE FR13_TORCH_PROF FR13_DVK_DRAFTID_DUMP
    FR10_TREE_GDN_CAPTURE_PAYLOAD FR10_TREE_GDN_COMMIT_HANDOFF_LOG
    FR10_TREE_GDN_SRC_NATIVE_PAYLOAD FR10_ROOT_HIDDEN_CAPTURE
    FR10_ROOT_LOGIT_CAPTURE FR10_LAYER_HIDDEN_CAPTURE
    FR12_FULL_ATTN_CAPTURE FR12_SUBKERNEL_CAPTURE
    FR13_TREE_ATTN_OP_CAPTURE FR13_FLASH_ATTN_OP_CAPTURE
    FR13_PREPROCESS_INPUT_CAPTURE FR13_PREFILL_GDN_CAPTURE
    FR13_DECODE_GDN_CAPTURE FR10_SPINE_LOGIT_CAPTURE
    FR13_FINAL_LOGIT_CAPTURE FR13_HIDDEN_SUBSTITUTE
    LUMO_MTP_DRAFT_TRACE_FILE LUMO_TREE_SAMPLER_DEBUG_LOG
    LUMO_TREE_PATH_LCP_LOG
  )
  for _fixed32_pin in "${_fixed32_required_empty[@]}"; do
    [[ -z "${!_fixed32_pin:-}" ]] \
      || { echo "fixed32 requires $_fixed32_pin to be empty" >&2; exit 2; }
  done
  unset _fixed32_pin _fixed32_required_one _fixed32_required_zero
  unset _fixed32_required_empty
fi

# FR13_ENABLE_APC (default 0): prefix caching for the GDN-hybrid. With spec-decode on,
# vLLM auto-forces mamba_cache_mode=align (config.py), which hard-requires chunked-prefill
# (a 2nd behavioral change). Qwen3-Next uses the SD conv layout (VLLM_SSM_CONV_STATE_LAYOUT
# unset -> "SD"), so is_conv_state_dim_first() is False -> the DS num_accepted>1 raise
# (mamba_utils.py:315) does NOT apply. fp32 SSM-state cache = SGLang default + vLLM #26807
# lossless lever. mamba_block_size multiple of 8 (causal_conv1d align), <= max-num-batched.
# BAKED default-ON 2026-07-27 (cleanup+bake): APC lossless proven (MISS==HIT byte-identical;
# blocksize fix baked); every S1/A-B gate arm ran APC=1. Export 0 to get the legacy no-cache boot.
FR13_ENABLE_APC=${FR13_ENABLE_APC:-1}
MAMBA_BLOCK_SIZE=${MAMBA_BLOCK_SIZE:-1024}
MAMBA_SSM_CACHE_DTYPE=${MAMBA_SSM_CACHE_DTYPE:-float32}
# APC LOSSLESS FIX (2026-06-21, proven run_20260621T013300Z): default max-num-batched-tokens to
# the mamba block size so each chunked-prefill scheduler step crosses AT MOST ONE block boundary.
# vLLM mamba 'align' caches ONE checkpoint per step (the last boundary it crosses); with a larger
# budget a step spans multiple blocks and an INTERMEDIATE boundary is cached with the step-END
# (overshoot) recurrent state (#45238), so a later cache hit at that boundary restores a grossly
# wrong GDN state -> degenerate 'output_text' garbage. step<=1 block => step-end state == boundary
# state => correct checkpoint => gross poison eliminated (cache-ON coherent + on-task, TTFT 3.96x).
# This is the minimum legal value (align asserts block_size <= max-num-batched). APC-scoped:
# consumed only inside APC_FLAGS below, so the non-APC locked cat9 serve command is byte-identical.
# (#43650 drop-final-block was REFUTED: the GDN restore reads block_table col-0 anchored to
# (seq_len-1)//block_size, NOT the matched-block count, so dropping a matched block is a no-op on
# the restored state. Stays default-OFF.)
# BAKED 2026-07-08 (serialization fix; shot output/fr13_serialization_shot): default raised 1024->4096
# to un-serialize co-resident decode (max_num_batched==block starved decode -> forced-4-concurrent
# Running mean 1.3->3.20). The #45238 gross-poison invariant (step<=1 block) is now re-enforced
# PER-REQUEST by --long-prefill-token-threshold=$MAMBA_BLOCK_SIZE (baked below), NOT by
# max_num_batched==block -> per-request chunk boundaries stay at the SAME 1024 positions (B=1 byte-
# identical; B>1 within-floor lossless: cache-ON clear-margin 4.55% < 12.90% floor, recurrent-oracle
# gated). Revert = set APC_MAX_NUM_BATCHED_TOKENS=$MAMBA_BLOCK_SIZE (the coupling assert below enforces
# that raising it REQUIRES the threshold, so you can't half-revert into #45238).
APC_MAX_NUM_BATCHED_TOKENS=${APC_MAX_NUM_BATCHED_TOKENS:-4096}
# AGGREGATE-THROUGHPUT probe (APC-OFF deploy path): extra serve flags appended verbatim. Default EMPTY =>
# byte-identical / no drift. Used to test whether the batch under-fill (effective_concurrency ~2.05 at B=4)
# is BUDGET-STARVED (raising --max-num-batched-tokens lets more streams' prefill+decode co-reside => higher
# aggregate tps) or AGENTIC-IDLE (streams paused between tool calls => no config fix). APC-off path sets no
# chunked-prefill/batch flags today (vLLM defaults), so this is untested for the deploy config.
FR13_SERVE_BATCH_FLAGS=${FR13_SERVE_BATCH_FLAGS:-}
# BAKED 2026-07-08 (serialization fix): per-request prefill-chunk cap = mamba block (was unset/OFF).
# Set here (before the coupling assert below) so the baked max_num_batched=4096 stays #45238-safe.
LUMO_LONG_PREFILL_THRESHOLD=${LUMO_LONG_PREFILL_THRESHOLD:-$MAMBA_BLOCK_SIZE}
if [[ "$FR13_ENABLE_APC" == "1" ]]; then
  # FR13_APC_CONFIG_ONLY=1 => apply the APC serve CONFIG (chunked-prefill + max-num-batched
  # + mamba flags) but WITHOUT --enable-prefix-caching. This is the matched-config cache-OFF
  # arm: it isolates the cache RESTORE (proven lossless within-boot) from the chunked-prefill
  # config that the cache REQUIRES (the gross-poison fix max_num_batched=1024 changes the GDN
  # chunk-boundary recurrence). Matched-config A/B = config_only vs full-APC, toggling only the cache.
  if [[ "${FR13_APC_CONFIG_ONLY:-0}" == "1" ]]; then
    # matched-config cache-OFF: only the chunked-prefill knobs that change GDN numerics.
    # The mamba-block-size/ssm-cache-dtype are cache-specific (vLLM rejects them without
    # --enable-prefix-caching), so they are dropped along with the cache flag.
    APC_FLAGS="--enable-chunked-prefill --max-num-batched-tokens $APC_MAX_NUM_BATCHED_TOKENS"
  else
    # FR13 64-align: in align mode mamba_block_size is OVERRIDDEN to block_size
    # (interface.py _align_hybrid_block_size L612-613), and block_size is only
    # kernel-aligned (16) -> 816, NOT a multiple of FLA_CHUNK_SIZE=64. Setting
    # --block-size to a 64-multiple (>= the ~816-token mamba page, <= max-num-batched)
    # forces a 64-aligned block_size so the mamba checkpoint at a block boundary is
    # BIT-EXACT (no residual).
    # BAKED 2026-07-04 (user): APC_BLOCK_SIZE now DEFAULTS to APC_MAX_NUM_BATCHED_TOKENS
    # (=MAMBA_BLOCK_SIZE=1024) instead of unset. Unset let vLLM pick 832 for tree arms,
    # violating the documented invariant (FR13_APC_EXACT_SEED_SUCCESS.md): block_size must
    # be (1) a 64-multiple [FLA_CHUNK_SIZE bit-exact boundary checkpoints], (2) >= ~816
    # [mamba page floor], (3) == max-num-batched [overshoot fix d228c76b / vLLM #45238:
    # one boundary per prefill step]. NOTE the 2026-07-04 A/B: 832-vs-1024 did NOT change
    # the tree+cache give-up (6/6 both geometries) — this bake is cache-correctness
    # hygiene, not the give-up fix (see FR13_TREECACHE_CAMPAIGN_20260704.md §8-9).
    # BAKED 2026-07-08 (serialization fix): APC_BLOCK_SIZE now pins to $MAMBA_BLOCK_SIZE (the mamba
    # page / GDN-checkpoint boundary), DECOUPLED from max_num_batched (was :=max_num_batched). The
    # old "(3) block_size == max_num_batched" #45238 invariant is superseded by the per-request
    # threshold below; block_size stays 1024 so the GDN checkpoint at a block boundary is bit-exact.
    APC_BLOCK_SIZE=${APC_BLOCK_SIZE:-$MAMBA_BLOCK_SIZE}
    if (( APC_BLOCK_SIZE % 64 != 0 )) || (( APC_BLOCK_SIZE < 816 )) || (( APC_BLOCK_SIZE > APC_MAX_NUM_BATCHED_TOKENS )); then
      echo "FAIL: APC_BLOCK_SIZE=$APC_BLOCK_SIZE violates the block-size invariant (64-multiple, >=816, <= max-num-batched=$APC_MAX_NUM_BATCHED_TOKENS)"; exit 2
    fi
    # COUPLING ASSERT (serialization-fix footgun-guard): raising max_num_batched above the mamba block
    # is ONLY safe when the per-request threshold re-enforces step<=1 block; otherwise #45238 gross-
    # poison (garbage cache-ON output) returns. Fail loud rather than silently corrupt.
    if (( APC_MAX_NUM_BATCHED_TOKENS > MAMBA_BLOCK_SIZE )); then
      if [[ -z "${LUMO_LONG_PREFILL_THRESHOLD:-}" ]] || (( LUMO_LONG_PREFILL_THRESHOLD > MAMBA_BLOCK_SIZE )); then
        echo "FAIL: APC_MAX_NUM_BATCHED_TOKENS=$APC_MAX_NUM_BATCHED_TOKENS > MAMBA_BLOCK_SIZE=$MAMBA_BLOCK_SIZE requires LUMO_LONG_PREFILL_THRESHOLD<=$MAMBA_BLOCK_SIZE (else #45238 gross-poison). Set the threshold or lower max_num_batched."; exit 2
      fi
    fi
    APC_FLAGS="--enable-prefix-caching --enable-chunked-prefill --mamba-block-size $MAMBA_BLOCK_SIZE --mamba-ssm-cache-dtype $MAMBA_SSM_CACHE_DTYPE --max-num-batched-tokens $APC_MAX_NUM_BATCHED_TOKENS --block-size $APC_BLOCK_SIZE"
    # SERIALIZATION-FIX flag (2026-07-08, wf_1c4af669 source-verified): per-request prefill-chunk cap.
    # BAKED default = $MAMBA_BLOCK_SIZE (set above). With APC_MAX_NUM_BATCHED_TOKENS=4096 + APC_BLOCK_SIZE
    # pinned to the mamba block, this breaks the decode-serialization (max_num_batched==block starved
    # co-resident decode) WITHOUT reintroducing the #45238 overshoot: the threshold re-enforces the
    # <=1-block-per-request-per-step invariant directly, so per-request chunk boundaries stay at the
    # same 1024 positions. GATED: shot output/fr13_serialization_shot PASSED throughput (forced-4-conc
    # Running mean 1.3->3.20) AND within-floor lossless (cache-ON clear-margin 4.55% < 12.90% floor,
    # recurrent-oracle). Empty LUMO_LONG_PREFILL_THRESHOLD reverts (but then also lower max_num_batched
    # per the coupling assert). Only added when APC_MAX_NUM_BATCHED_TOKENS>block (else it is a no-op).
    if [[ -n "${LUMO_LONG_PREFILL_THRESHOLD:-}" ]]; then
      APC_FLAGS="$APC_FLAGS --long-prefill-token-threshold $LUMO_LONG_PREFILL_THRESHOLD"
    fi
  fi
  # SNAP_FIX/CONV_SNAP_FIX/PRE_SNAP_FIX/CONV_LEAF_COMPLETE (the tree+APC node-bank leaf-map
  # redirect family) DELETED 2026-07-22: STATELESS-TREE's own get_temporal_copy_spec/
  # get_conv_copy_spec stock rewrite (col-0 direct read under FR13_APC_COMMIT_TO_RUNNING_ROW=1)
  # makes the redirect provably unreachable/unnecessary under the deployed default -- proven via
  # direct code trace (SSM) + adversarial workflow (CONV, wf_207a3da7-ef0). See
  # project_fr13_snapfix_pb_cleanup.md. CONV_FIX/CONV_SNAPSHOT (the separate, independently-
  # baked mechanism that makes get_conv_copy_spec's stock branch correct) is UNCHANGED.
  : "${FR13_APC_CONV_FIX:=1}"
  : "${FR13_APC_CONV_SNAPSHOT:=1}"
  # BAKED 2026-07-06 (user): the two tree+cache give-up CARRIER FIXES default ON. Together they
  # fill the campaign's missing cell — tree+cache now resolves nudge-free like tree+no-cache
  # (give-up class extinct 0/9 live runs; rp5 probe 24/24 route parity; i6 RESOLVED through a 103s
  # offload wedge). Both default-OFF-byte-identical; cache-OFF / native unaffected.
  #  - ZERO_MAMBA_ON_ALLOC (§48/E5): zero recycled GDN conv/ssm pool rows on fresh alloc (vLLM
  #    zeroes only full-attn blocks) so request N can't read request N-1's residue on the cold path.
  #    PATCH-TIME gated => MUST be =1 here or the zeroing injection is skipped entirely.
  : "${FR13_APC_ZERO_MAMBA_ON_ALLOC:=1}"
  #  - COPY_SRC_FIX (§52/§53): freshness-gate the tree->linear accept-bias so a stale batch-position
  #    accepted-tree can't poison the chunk-boundary state-copy SOURCE (was propagating zeros to
  #    every request after the first). Runtime-gated (default ON); decode-boundary byte-identical.
  : "${FR13_APC_COPY_SRC_FIX:=1}"
  #  - FREE_TREE_POSGLOBALS (§112/carrier-B): clear the never-cleared batch-position
  #    tree_mtp accepted-tree globals on _free_request so a concurrent agent reusing
  #    batch-position 0 can't read the freed request's residue. Default 0 (byte-identical);
  #    flip to 1 only after the B=4 gate confirms 0/4 -> ~4/4.
  : "${FR13_FREE_TREE_POSGLOBALS:=0}"
  export FR13_APC_CONV_FIX FR13_APC_CONV_SNAPSHOT FR13_APC_ZERO_MAMBA_ON_ALLOC FR13_APC_COPY_SRC_FIX FR13_FREE_TREE_POSGLOBALS
else
  APC_FLAGS=""
fi

# CUDAGRAPH_MODE — FULL GRAPH IS THE DEFAULT (FR13 BAKED 2026-06-30).
# HISTORY (CARRIER 2026-06-21): full-graph cache-ON produced garble — the FULL decode CUDA-graph
# reads GDN recurrent state via persistent block-pool indexing, and after an APC cache-hit re-prefill
# the captured graph appeared to read the wrong row -> garbage (align-mode sibling of vLLM #34874 /
# #43559). The interim mitigation was cudagraph_mode=PIECEWISE (run the GDN/mamba scan EAGER every
# step), which preserved dense-GEMM graph capture but cost the GDN-scan decode TPS.
# RESOLVED (not a graph bug): the garble was a SYMPTOM of the cache restoring the WRONG mamba
# node-bank row on a cache-hit re-prefill, not the captured graph reading a stale index. The baked
# SNAP_FIX / CONV_SNAP_FIX node-bank redirects (restore the committed-accepted-leaf column instead of
# the base block-pool row) make cache-restore correct, so FULL_AND_PIECEWISE + cache-ON is garble-free
# — probe run_20260630T030153Z: "Capturing CUDA graphs" + enforce_eager=False + 46/55 cached turns,
# CJK=0, coherent. So default to FULL graph for decode-TPS recovery; override CUDAGRAPH_MODE=PIECEWISE
# only for diagnostics. Only matters with APC on.
CUDAGRAPH_MODE="${CUDAGRAPH_MODE:-FULL_AND_PIECEWISE}"
CG_FLAGS="--compilation-config '{\"cudagraph_mode\":\"$CUDAGRAPH_MODE\"}'"
# FR13_FULL_ATTN_KV_FP8 (gated, default OFF): set the FULL-ATTENTION KV cache to fp8.
# DISCRIMINATOR for the APC tree residual locus (research w284wg523, #43559): fp8 KV
# only touches full-attn KV storage precision, never the mamba/GDN recurrent state.
# If cat6root+APC+fp8KV recovers the agent -> residual is FULL-ATTN-KV (the post-RoPE-K
# boundary seam); if not -> GDN-state-content. (The #43559 fp8-recovery claim was struck
# unverified, so treat this strictly as a DISCRIMINATOR, validate losslessness before any
# ship.) Off -> kv_cache_dtype=auto (byte-identical to now). Only meaningful with APC on.
KV_FP8_FLAGS=""
if [[ "${FR13_FULL_ATTN_KV_FP8:-0}" == "1" ]]; then
  KV_FP8_FLAGS="--kv-cache-dtype fp8"
fi

if [[ ! -f "$FORKED_FA2_SO" ]]; then
  echo "forked FA2 .so not found: $FORKED_FA2_SO" >&2
  exit 2
fi
if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  FR13_FIXED32_B1_DIAGNOSTIC=${FR13_FIXED32_B1_DIAGNOSTIC:-0}
  FR13_B1_DIAGNOSTIC_TASK_PROFILE=${FR13_B1_DIAGNOSTIC_TASK_PROFILE:-astropy12907}
  _fr13_fixed32_sfwd_state_fusion_diagnostic=${FR13_FIXED32_SFWD_STATE_FUSION_BYTE_AB:-0}
  _fr13_fixed32_sfwd_state_fusion_timing=${FR13_FIXED32_SFWD_STATE_FUSION_TIMING_AB:-0}
  _fr13_fixed32_sfwd_state_fusion_production=${FR13_FIXED32_SFWD_STATE_FUSION_PRODUCTION:-0}
  _fr13_fixed32_sfwd_conv_postprep=${FR13_FIXED32_SFWD_CONV_POSTPREP_FUSION:-0}
  _fr13_fixed32_sfwd_conv_postprep_byte=${FR13_FIXED32_SFWD_CONV_POSTPREP_BYTE_AB:-0}
  _fr13_fixed32_sfwd_embed_gate=${FR13_FIXED32_SFWD_EMBED_GATE_CTA:-0}
  _fr13_fixed32_sfwd_nodegroup8_direct=${FR13_FIXED32_SFWD_NODEGROUP8_DIRECT:-0}
  _fr13_fixed32_sfwd_prior_reuse=${FR13_FIXED32_SFWD_PRIOR_REUSE_BYTE_AB:-0}
  _fr13_fixed32_batch_gdn_diagnostic=${FR13_FIXED32_BATCH_GDN_BYTE_AB:-0}
  _fr13_fixed32_batch_gdn_graph_diagnostic=${FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB-0}
  _fr13_fixed32_sfwd_b4_diagnostic=${FR13_FIXED32_SFWD_STATE_FUSION_BYTE_AB:-0}
  case "$FR13_FIXED32_B1_DIAGNOSTIC" in
    0|1) ;;
    *) echo "FR13_FIXED32_B1_DIAGNOSTIC must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$FR13_B1_DIAGNOSTIC_TASK_PROFILE" in
    astropy12907) _fr13_b1_diagnostic_task_id=astropy__astropy-12907 ;;
    astropy13236) _fr13_b1_diagnostic_task_id=astropy__astropy-13236 ;;
    *) echo "FR13_B1_DIAGNOSTIC_TASK_PROFILE is unsupported" >&2; exit 2 ;;
  esac
  if [[ "$FR13_FIXED32_B1_DIAGNOSTIC" != "1" \
        && "$FR13_B1_DIAGNOSTIC_TASK_PROFILE" != "astropy12907" ]]; then
    echo "alternate B1 task profile requires diagnostic mode" >&2
    exit 2
  fi
  export FR13_B1_DIAGNOSTIC_TASK_PROFILE
  case "$_fr13_fixed32_sfwd_state_fusion_diagnostic" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_STATE_FUSION_BYTE_AB must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_state_fusion_timing" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_STATE_FUSION_TIMING_AB must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_prior_reuse" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_PRIOR_REUSE_BYTE_AB must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_state_fusion_production" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_STATE_FUSION_PRODUCTION must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_conv_postprep" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_CONV_POSTPREP_FUSION must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_conv_postprep_byte" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_CONV_POSTPREP_BYTE_AB must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_embed_gate" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_EMBED_GATE_CTA must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_nodegroup8_direct" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_NODEGROUP8_DIRECT must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  [[ "$_fr13_fixed32_sfwd_embed_gate" == "0" \
     || ( "$_fr13_fixed32_sfwd_conv_postprep_byte" == "1" \
          && "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" ) ]] || {
    echo "embedded gate CTA requires the Hydra27 conv/post-prep byte gate" >&2
    exit 2
  }
  [[ "$_fr13_fixed32_sfwd_nodegroup8_direct" == "0" \
     || ( "$_fr13_fixed32_sfwd_conv_postprep_byte" == "1" \
          && "$_fr13_fixed32_sfwd_conv_postprep" == "0" \
          && "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" \
          && "${MAX_NUM_SEQS:-}" == "1" \
          && "${SWE_CONCURRENCY:-}" == "1" ) ]] || {
    echo "direct nodegroup8 requires the Hydra27 B1 conv/post-prep byte gate" >&2
    exit 2
  }
  _fr13_fixed32_sfwd_route_count=$((
    10#$_fr13_fixed32_sfwd_state_fusion_diagnostic
    + 10#$_fr13_fixed32_sfwd_state_fusion_timing
    + 10#$_fr13_fixed32_sfwd_state_fusion_production
    + 10#$_fr13_fixed32_sfwd_prior_reuse
    + 10#$_fr13_fixed32_sfwd_conv_postprep
    + 10#$_fr13_fixed32_sfwd_conv_postprep_byte
  ))
  if (( _fr13_fixed32_sfwd_route_count > 1 )); then
    echo "fixed32 SFWD diagnostics and production are mutually exclusive" >&2
    exit 2
  fi
  case "$_fr13_fixed32_batch_gdn_diagnostic" in
    0|1) ;;
    *) echo "FR13_FIXED32_BATCH_GDN_BYTE_AB must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_batch_gdn_graph_diagnostic" in
    0|1) ;;
    *) echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  case "$_fr13_fixed32_sfwd_b4_diagnostic" in
    0|1) ;;
    *) echo "FR13_FIXED32_SFWD_STATE_FUSION_BYTE_AB must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  _fr13_fixed32_batch_gdn_bv8_timing="${FR13_FIXED32_BATCH_GDN_BV8_TIMING:-0}"
  case "$_fr13_fixed32_batch_gdn_bv8_timing" in
    0|1) ;;
    *) echo "FR13_FIXED32_BATCH_GDN_BV8_TIMING must be exactly 0 or 1" >&2; exit 2 ;;
  esac
  if [[ "$_fr13_fixed32_batch_gdn_diagnostic" == "1" \
        && "$_fr13_fixed32_batch_gdn_graph_diagnostic" == "1" ]]; then
    echo "fixed32 eager and graph batched GDN diagnostics are mutually exclusive" >&2
    exit 2
  fi
  if [[ ( "$_fr13_fixed32_batch_gdn_diagnostic" == "1" \
          || "$_fr13_fixed32_batch_gdn_graph_diagnostic" == "1" ) \
        && "$MAX_NUM_SEQS" != "4" ]]; then
    echo "fixed32 batched GDN byte diagnostic requires MAX_NUM_SEQS=4" >&2
    exit 2
  fi
  if [[ "$_fr13_fixed32_sfwd_b4_diagnostic" == "1" \
        && "$MAX_NUM_SEQS" != "4" ]]; then
    echo "fixed32 SFWD state-fusion byte diagnostic requires MAX_NUM_SEQS=4" >&2
    exit 2
  fi
  if [[ "$FR13_FIXED32_B1_DIAGNOSTIC" == "1" && "$MAX_NUM_SEQS" != "1" ]]; then
    echo "fixed32 B1 diagnostic requires MAX_NUM_SEQS=1" >&2
    exit 2
  fi
  if [[ "$_fr13_fixed32_sfwd_prior_reuse" == "1" \
        && ( "$FR13_FIXED32_B1_DIAGNOSTIC" != "1" \
             || "$MAX_NUM_SEQS" != "1" ) ]]; then
    echo "fixed32 SFWD prior-reuse byte gate requires the B1 diagnostic" >&2
    exit 2
  fi
  if [[ "$_fr13_fixed32_sfwd_conv_postprep" == "1" \
        && "$MAX_NUM_SEQS" != "1" \
        && "$MAX_NUM_SEQS" != "4" ]]; then
    echo "fixed32 SFWD conv/post-prep fusion requires MAX_NUM_SEQS=1 or 4" >&2
    exit 2
  fi
  _fixed32_expected_mem=105g
  _fixed32_expected_kv_cache_memory_bytes=
  if [[ "$MAX_NUM_SEQS" == "4" ]]; then
    _fixed32_expected_mem=112g
    _fixed32_expected_kv_cache_memory_bytes=49392123904
    KV_CACHE_MEMORY_BYTES=${KV_CACHE_MEMORY_BYTES:-$_fixed32_expected_kv_cache_memory_bytes}
  fi
  _fixed32_expected_metrics=0
  _fixed32_expected_eager=0
  if [[ "$_fr13_fixed32_batch_gdn_diagnostic" == "1" \
        || "$_fr13_fixed32_batch_gdn_graph_diagnostic" == "1" \
        || "$_fr13_fixed32_batch_gdn_bv8_timing" == "1" \
        || "$_fr13_gdn_path_bv_candidate" == "single_launch" \
        || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
        || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" \
        || "$_fr13_gdn_gqa_group3_production" == "1" \
        || "$_fr13_gdn_single_launch_production" == "1" \
        || "$_fr13_gdn_single_launch_timing_control" == "1" \
        || ( "${FR13_FIXED32_BATCH_GDN_PRODUCTION:-0}" == "1" \
             && "${FR13_FIXED32_BATCH_GDN_BV_PRODUCTION:-}" == "8" ) ]]; then
    # This is a real exact4 byte diagnostic, never an acceptance/timing arm.
    # Both execution modes require the invocation counter for byte evidence.
    _fixed32_expected_metrics=1
  fi
  if [[ "$_fr13_fixed32_batch_gdn_diagnostic" == "1" ]]; then
    _fixed32_expected_eager=1
  fi
  if [[ "$_fr13_fixed32_sfwd_state_fusion_diagnostic" == "1" \
        || "$_fr13_fixed32_sfwd_state_fusion_timing" == "1" \
        || "$_fr13_fixed32_sfwd_state_fusion_production" == "1" \
        || "$_fr13_fixed32_sfwd_prior_reuse" == "1" \
        || "$_fr13_fixed32_sfwd_conv_postprep_byte" == "1" \
        || ( "$_fr13_fixed32_sfwd_conv_postprep" == "1" \
             && "${ENFORCE_EAGER:-0}" == "1" ) ]]; then
    _fixed32_expected_eager=1
  fi
  if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "streamk_coop128_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "streamk_force_wide256_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "static_persistent_stocktile_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "divisor_static_stocktile_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stage2_static_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stage2_pingpong_b1_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_onen_b1_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_onen_n5120_single_b1_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_onen_n5120_fullgrid_b1_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_wide256_fullgrid_b1_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_divisor_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_stage2_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_twom_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_hybrid_n5120_b4_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_byte_ab" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_static_byte_ab" ]]; then
    _fixed32_expected_eager=1
  fi
  case "${FR13_DRAFT_VOCAB_K:-65536}:$FR13_DRAFT_VOCAB_ROOT" in
    0:0)
      [[ ( "$MAX_NUM_SEQS" == "1" || "$MAX_NUM_SEQS" == "4" ) \
         && "${FR13_NEEDS_ALLOW:-}" == "FR13_DRAFT_VOCAB_K=0" ]] || {
        echo "fixed32 full-vocabulary mode requires exact B1/B4 and its sanctioned override" >&2
        exit 2
      }
      _fixed32_expected_draft_vocab_k=0
      _fixed32_expected_mandatory_weight_bytes=25430574256
      _fixed32_expected_weight_floor_ms=93.15228665201465
      ;;
    65536:0)
      _fixed32_expected_draft_vocab_k=65536
      _fixed32_expected_mandatory_weight_bytes=25254282384
      _fixed32_expected_weight_floor_ms=92.506528879
      ;;
    65536:1)
      _fixed32_expected_draft_vocab_k=65536
      # FR14 RETIRED ARM -- see scripts/fr13_fixed32_floor_timers_seq.sh for
      # the full reasoning. Arm B serves an NVFP4 lm_head and PHASE 1 of the
      # DVK port dequantises the sliced K64 rows to BF16 at boot, so the five
      # draft-head reads are BF16 and there is no FP8 head to price; refuse
      # instead of pinning a floor nothing can hit. (The live successor is the
      # PHASE-2 NVFP4 draft-head read, worth a real 8.834 ms, which needs an
      # FP4 GEMV unit and its own byte gate -- not this arm.)
      if [[ "$FR13_DRAFT_HEAD_FP8" == "1" ]]; then
        echo "FR13_DRAFT_HEAD_FP8 is RETIRED under the FR14 NVFP4 checkpoint: the served head is NVFP4 and its K64 slice is dequantised to BF16 at boot, so the FP8 draft-head floor is unrealisable" >&2
        exit 2
      fi
      _fixed32_expected_mandatory_weight_bytes=25210209416
      _fixed32_expected_weight_floor_ms=92.345089436
      ;;
    *)
      echo "fixed32 draft-vocab floor configuration is unsupported: K=${FR13_DRAFT_VOCAB_K:-unset} ROOT=$FR13_DRAFT_VOCAB_ROOT" >&2
      exit 2
      ;;
  esac
  [[ "$MAX_NUM_SEQS" == "1" || "$MAX_NUM_SEQS" == "4" ]] \
    || { echo "fixed32 requires MAX_NUM_SEQS=1 or 4" >&2; exit 2; }
  _fixed32_exact_pairs=(
    "GPU_UTIL|$GPU_UTIL|0.70"
    "MAX_MODEL_LEN|$MAX_MODEL_LEN|131072"
    "KV_CACHE_MEMORY_BYTES|$KV_CACHE_MEMORY_BYTES|$_fixed32_expected_kv_cache_memory_bytes"
    "DOCKER_MEM_CAP|$DOCKER_MEM_CAP|$_fixed32_expected_mem"
    "ATTENTION_BACKEND|$ATTENTION_BACKEND|TREE_ATTN"
    "FR10_DECODE_MODE_DEFAULT|$FR10_DECODE_MODE_DEFAULT|tree_mtp"
    "FR10_METRICS|$FR10_METRICS|$_fixed32_expected_metrics"
    "FR13_RING_EXPORT|${FR13_RING_EXPORT:-1}|1"
    "FR13_FLAGS_INKERNEL|${FR13_FLAGS_INKERNEL:-1}|1"
    "FR13_SCAN_ALIGN|${FR13_SCAN_ALIGN:-0}|0"
    "FR13_NPAD_INVARIANT|${FR13_NPAD_INVARIANT:-0}|0"
    "BATCH_INVARIANT|$BATCH_INVARIANT|0"
    "FR13_TAIL_MODE|${FR13_TAIL_MODE:-0}|1"
    "FR13_DRAFT_SOURCE|${FR13_DRAFT_SOURCE:-mtp}|merged"
    "FR13_TREE_GDN_GEOM_OVERRIDE|${FR13_TREE_GDN_GEOM_OVERRIDE:-}|$_fr13_fixed32_expected_gdn_geom"
    "FR13_HYDRA23|${FR13_HYDRA23:-0}|0"
    "FR13_TAIL_BRANCHES|${FR13_TAIL_BRANCHES:-0}|0"
    "FR13_TAIL_BRANCH_DEPTHS|${FR13_TAIL_BRANCH_DEPTHS:-0}|0"
    "FR13_FA2_PREFILL_NATIVE|$FR13_FA2_PREFILL_NATIVE|1"
    "FR13_TREE_ATTN_EXP2_SOFTMAX|$FR13_TREE_ATTN_EXP2_SOFTMAX|1"
    "FR13_BI_TREE_ATTN|$FR13_BI_TREE_ATTN|0"
    "FR13_ENABLE_APC|$FR13_ENABLE_APC|1"
    "FR13_APC_CONFIG_ONLY|${FR13_APC_CONFIG_ONLY:-0}|0"
    "MAMBA_BLOCK_SIZE|$MAMBA_BLOCK_SIZE|1024"
    "MAMBA_SSM_CACHE_DTYPE|$MAMBA_SSM_CACHE_DTYPE|float32"
    "APC_MAX_NUM_BATCHED_TOKENS|$APC_MAX_NUM_BATCHED_TOKENS|4096"
    "APC_BLOCK_SIZE|$APC_BLOCK_SIZE|1024"
    "LUMO_LONG_PREFILL_THRESHOLD|$LUMO_LONG_PREFILL_THRESHOLD|1024"
    "CUDAGRAPH_MODE|$CUDAGRAPH_MODE|FULL_AND_PIECEWISE"
    "FR13_FULL_ATTN_KV_FP8|${FR13_FULL_ATTN_KV_FP8:-0}|0"
    "ENFORCE_EAGER|${ENFORCE_EAGER:-0}|$_fixed32_expected_eager"
    "SEED|${SEED:-0}|0"
    "PYTORCH_CUDA_ALLOC_CONF|$PYTORCH_CUDA_ALLOC_CONF|expandable_segments:True"
    "GPU_OOM_GUARD|$GPU_OOM_GUARD|1"
    "LUMO_FB_KERNEL_ROWS|$LUMO_FB_KERNEL_ROWS|1"
    "LUMO_FB_PROJ_PAD_ROWS|$LUMO_FB_PROJ_PAD_ROWS|16"
    "FR13_INPUTPREP_GUARD|${FR13_INPUTPREP_GUARD:-}|1"
    "FR13_DRAFT_VOCAB_K|${FR13_DRAFT_VOCAB_K:-}|$_fixed32_expected_draft_vocab_k"
    "FR13_DRAFT_HEAD_FP8|$FR13_DRAFT_HEAD_FP8|$FR13_DRAFT_HEAD_FP8"
    "FR13_DRAFT_VOCAB_BLOCKS|${FR13_DRAFT_VOCAB_BLOCKS:-}|/workspace/scripts/fr13_dvk_subset_blocks.json"
    "FR13_APC_CONV_FIX|${FR13_APC_CONV_FIX:-}|1"
    "FR13_APC_CONV_SNAPSHOT|${FR13_APC_CONV_SNAPSHOT:-}|1"
    "FR13_APC_ZERO_MAMBA_ON_ALLOC|${FR13_APC_ZERO_MAMBA_ON_ALLOC:-}|1"
    "FR13_APC_COPY_SRC_FIX|${FR13_APC_COPY_SRC_FIX:-}|1"
    "FR13_FREE_TREE_POSGLOBALS|${FR13_FREE_TREE_POSGLOBALS:-}|0"
    "FR13_APC_BLOCK_ALIGN_45477|${FR13_APC_BLOCK_ALIGN_45477:-1}|1"
    "FR13_SFWD_GPU_TIMER_MAXPENDING|${FR13_SFWD_GPU_TIMER_MAXPENDING:-}|256"
    "FR13_SFWD_GPU_TIMER_SAMPLES_MAX|${FR13_SFWD_GPU_TIMER_SAMPLES_MAX:-}|200000"
    "FR13_SFWD_GPU_TIMER_DUMP_S|${FR13_SFWD_GPU_TIMER_DUMP_S:-}|0"
    "FR13_SFWD_SAMPLES_DUMP_S|${FR13_SFWD_SAMPLES_DUMP_S:-}|30"
    "FR13_SPAN_GPU_TIMER_DUMP_S|${FR13_SPAN_GPU_TIMER_DUMP_S:-}|0"
    "FR13_STEP_WALL_CAP_S|${FR13_STEP_WALL_CAP_S:-}|1.5"
    "FR13_MANDATORY_WEIGHT_BYTES|${FR13_MANDATORY_WEIGHT_BYTES:-}|$_fixed32_expected_mandatory_weight_bytes"
    "FR13_WEIGHT_FLOOR_MS|${FR13_WEIGHT_FLOOR_MS:-}|$_fixed32_expected_weight_floor_ms"
    "FR13_COMPUTE_MS_PER_ROW|${FR13_COMPUTE_MS_PER_ROW:-}|0.54"
  )
  for _fixed32_pair in "${_fixed32_exact_pairs[@]}"; do
    IFS='|' read -r _fixed32_name _fixed32_actual _fixed32_expected \
      <<< "$_fixed32_pair"
    [[ "$_fixed32_actual" == "$_fixed32_expected" ]] || {
      echo "fixed32 requires $_fixed32_name=$_fixed32_expected, got $_fixed32_actual" >&2
      exit 2
    }
  done
  [[ -z "$FR13_SERVE_BATCH_FLAGS" ]] \
    || { echo "fixed32 forbids FR13_SERVE_BATCH_FLAGS" >&2; exit 2; }
  # The B1 binary-identity preflight below resolves its pin arm from these two
  # variables, so make them visible to the child interpreter regardless of how
  # the caller set them.
  # Site 24's CONSUMER. This child interpreter runs
  # fr13_fixed32_contract._expected_runtime_fa2_identity, so teaching that
  # resolver TIER_B_ARM is worth nothing unless the variable actually reaches
  # it. A resolver that knows a selector it cannot see is still stranded.
  export FR13_FA2_QROW32_B1_LIVE_AB_ARM FR13_FA2_QROW32_B1_PRODUCTION_ARM \
         FR13_FA2_QROW32_B1_TIER_B_ARM
  PYTHONPATH="$REPO/scripts" .venv/bin/python - \
    "$REPO" "$IMAGE" "$FORKED_FA2_SO" "$TREE" "$SPEC_CONFIG" \
    "$_FR13_FA2_QROW16_CANDIDATE_MODE" "$FR13_FA2_QROW16_SO_SHA256" \
    "$_FR13_FA2_QROW32_CANDIDATE_MODE" "$FR13_FA2_QROW32_SO_SHA256" \
    "$_FR13_FA2_QROW32_B1_CANDIDATE_MODE" "$FR13_FA2_QROW32_B1_SO_SHA256" \
    "$_FR13_FA2_QROW32_B4_CANDIDATE_MODE" "${FR13_FIXED32_MODE:-}" <<'PY'
import os
import sys
from pathlib import Path

import fr13_fixed32_contract as contract

(
    repo,
    image,
    fa2_raw,
    tree,
    spec_config,
    qrow16_candidate,
    qrow16_sha256,
    qrow32_candidate,
    qrow32_sha256,
    qrow32_b1_candidate,
    qrow32_b1_sha256,
    qrow32_b4_candidate,
    fixed32_mode,
) = sys.argv[1:]
# Round 16: this block used to compare the dispatched TREE/SPEC_CONFIG against
# PARAMETERLESS contract accessors, which encoded hydra27's tree -- so a hydra31
# arm was refused here no matter what it dispatched, and fixing one accessor
# only moved the refusal to the next line. The arm's own mode now selects the
# profile. Empty means "the caller named no profile", which is hydra27 exactly
# as before (this is the pairing-evidence path); an unknown mode is refused
# rather than silently answered for by hydra27's tree.
if fixed32_mode == "":
    fixed32_mode = contract.PROFILE_HYDRA27
try:
    contract.tree_profile(fixed32_mode)
except contract.ContractError as exc:
    raise SystemExit(str(exc)) from None
fa2 = Path(fa2_raw).resolve(strict=True)
expected_fa2 = Path(repo).resolve() / contract.FA2_REPO_RELATIVE
if image != contract.IMAGE_REFERENCE:
    raise SystemExit(f"fixed32 image override is forbidden: {image!r}")
contract._docker_image_record()
actual_sha256 = contract.sha256_file(fa2)
if qrow16_candidate == "1":
    if actual_sha256 != qrow16_sha256:
        raise SystemExit("fixed32 qrow16 candidate FA2 sha256 mismatch")
    if actual_sha256 == contract.FA2_SHA256:
        raise SystemExit("fixed32 qrow16 live gate received the stock FA2 binary")
elif qrow32_candidate == "1":
    if actual_sha256 != qrow32_sha256:
        raise SystemExit("fixed32 qrow32 candidate FA2 sha256 mismatch")
    if actual_sha256 == contract.FA2_SHA256:
        raise SystemExit("fixed32 qrow32 live gate received the stock FA2 binary")
elif qrow32_b4_candidate == "1":
    # Both timing arms load this binary; only the served kernel differs, so the
    # stock-dispatch arm must carry the SAME pinned candidate identity.
    if actual_sha256 != qrow32_sha256:
        raise SystemExit("fixed32 qrow32 B4 candidate FA2 sha256 mismatch")
    if (
        actual_sha256 != contract.QROW32_B4_GQA_PAIR_FA2_SHA256
        or fa2.stat().st_size != contract.QROW32_B4_GQA_PAIR_FA2_SIZE
    ):
        raise SystemExit("fixed32 qrow32 B4 binary identity is not qualified")
elif qrow32_b1_candidate == "1":
    if actual_sha256 != qrow32_b1_sha256:
        raise SystemExit("fixed32 qrow32 B1 candidate FA2 sha256 mismatch")
    # SITE 23, and it closes the loop on site 17. Site 17 replaced a
    # `.get(arm, split2_pins)` with a table -- but the table kept an "" key,
    # and this resolver never learned the tier-B spelling, so a tier-B boot
    # resolved "" and the "" key handed back split2's pins. The runner's words
    # are now doctrine: NAMING A DEFAULT DOES NOT REMOVE IT; THE REMOVAL HAS TO
    # HAPPEN AT THE RESOLVER, NOT THE TABLE.
    #
    # So the resolver is made TOTAL, and it is made total against the
    # ENVIRONMENT rather than against a list of keys somebody remembered to
    # update. Any FR13_FA2_QROW32_B1_*_ARM variable that is set and that this
    # resolver does not know about is a refusal -- which is the property that
    # would have caught rounds 2.1, 17 and 23 before any of them booted, and
    # which catches the 24th selector nobody has written yet.
    #
    # Precedence mirrors the bash pin case exactly: live, then tier-b, then
    # production. That claim is no longer a comment -- a CPU twin-equivalence
    # test executes both resolvers and compares them arm by arm.
    _b1_pin_selectors = (
        "FR13_FA2_QROW32_B1_LIVE_AB_ARM",
        "FR13_FA2_QROW32_B1_TIER_B_ARM",
        "FR13_FA2_QROW32_B1_PRODUCTION_ARM",
    )
    # Known to exist and deliberately NOT pin-deciding. Named so that the
    # sweep below stays meaningful instead of being widened until it passes.
    _b1_non_pin_selectors = ("FR13_FA2_QROW32_B1_TIMING_ARM",)
    _b1_unknown = sorted(
        name
        for name, value in os.environ.items()
        if name.startswith("FR13_FA2_QROW32_B1_")
        and name.endswith("_ARM")
        and value
        and name not in _b1_pin_selectors
        and name not in _b1_non_pin_selectors
    )
    if _b1_unknown:
        raise SystemExit(
            "fixed32 qrow32 B1 pin-arm resolver does not know these selectors, "
            "so it cannot say which binary they authorise: "
            + ", ".join(_b1_unknown)
        )
    _b1_named = [
        os.environ.get(name, "") for name in _b1_pin_selectors
    ]
    _b1_named = [value for value in _b1_named if value]
    if len(_b1_named) > 1:
        raise SystemExit(
            "fixed32 qrow32 B1 selectors are mutually exclusive; named: "
            + ", ".join(_b1_named)
        )
    # No selector named at all is the incumbent, and it is spelled OUT rather
    # than left as "" -- because "" was also what a resolver that failed to
    # look produced, and the two must not be the same value.
    b1_pin_arm = _b1_named[0] if _b1_named else "nosplit"
    expected = {
        "visibility": (
            contract.QROW32_B1_VISIBILITY_FA2_SHA256,
            contract.QROW32_B1_VISIBILITY_FA2_SIZE,
        ),
        "gqa_pair": (
            contract.QROW32_B1_GQA_PAIR_FA2_SHA256,
            contract.QROW32_B1_GQA_PAIR_FA2_SIZE,
        ),
        # FR14 lane 4 split-K (tier-b). Arm S's live boot died right here at
        # "binary identity is not qualified": the split-K pins had landed in
        # the bash pin case twenty lines of comment away, but this map had no
        # entry, so the arm fell through to split2's identity. A fall-through
        # default that silently answers for an arm it was not written for is
        # the defect; naming every arm is the fix, and the assertion below
        # turns any future unnamed arm into a refusal instead of a wrong pin.
        "gqa_pair_splitk": (
            contract.QROW32_B1_SPLITK_FA2_SHA256,
            contract.QROW32_B1_SPLITK_FA2_SIZE,
        ),
        # nosplit and split2 share one binary, and they are NAMED rather than
        # defaulted. The .get() default this replaced answered for every arm
        # nobody had written a key for -- with split2's identity -- which is
        # the 17th site's defect shape exactly.
        "nosplit": (
            contract.QROW32_B1_SPLIT2_FA2_SHA256,
            contract.QROW32_B1_SPLIT2_FA2_SIZE,
        ),
        "split2": (
            contract.QROW32_B1_SPLIT2_FA2_SHA256,
            contract.QROW32_B1_SPLIT2_FA2_SIZE,
        ),
    }.get(b1_pin_arm)
    if expected is None:
        raise SystemExit(
            "fixed32 qrow32 B1 arm has no pinned binary identity: "
            f"{b1_pin_arm!r}"
        )
    expected_sha256, expected_size = expected
    if b1_pin_arm in contract.QROW32_B1_TIER_B_ARMS and (
        expected_sha256 != contract.QROW32_B1_SPLITK_FA2_SHA256
    ):
        raise SystemExit(
            "fixed32 qrow32 B1 tier-b arm resolved a non-tier-b binary"
        )
    if not expected_sha256 or not expected_size:
        raise SystemExit(
            f"fixed32 qrow32 B1 arm {b1_pin_arm!r} has no pinned binary identity"
        )
    if actual_sha256 != expected_sha256 or fa2.stat().st_size != expected_size:
        raise SystemExit("fixed32 qrow32 B1 binary identity is not qualified")
else:
    if fa2 != expected_fa2:
        raise SystemExit(f"fixed32 FA2 realpath mismatch: {fa2} != {expected_fa2}")
    if fa2.stat().st_size != contract.FA2_SIZE:
        raise SystemExit("fixed32 FA2 size mismatch")
    if actual_sha256 != contract.FA2_SHA256:
        raise SystemExit("fixed32 FA2 sha256 mismatch")
if tree != contract.fixed32_tree_text(fixed32_mode):
    raise SystemExit(
        f"fixed32 TREE text differs from canonical contract for {fixed32_mode}"
    )
if spec_config != contract.speculative_config_text(fixed32_mode):
    raise SystemExit(
