    2>/dev/null || true
  FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH=
fi
export FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH
if [[ "$_fr13_sfwd_prior_reuse" != "1" ]]; then
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.source_manifest.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.byte_ab.jsonl" \
    2>/dev/null || true
fi
if [[ "$_fr13_batch_gdn_production" == "1" ]]; then
  [[ -n "${FR13_FIXED32_MODE:-}" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_PRODUCTION requires FR13_FIXED32_MODE" >&2; exit 2; }
  [[ "$MAX_NUM_SEQS" =~ ^[234]$ ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_PRODUCTION requires MAX_NUM_SEQS=2, 3, or 4" >&2; exit 2; }
  if [[ -n "$_fr13_batch_gdn_bv_production" ]]; then
    [[ "$MAX_NUM_SEQS" == "4" ]] \
      || { echo "FR13 fixed32 batched B4 GDN production requires MAX_NUM_SEQS=4" >&2; exit 2; }
    if [[ "$_fr13_batch_gdn_bv_production" == "8" ]]; then
      [[ "${FR13_FIXED32_MODE:-}" == "tail6_fixed32" \
         || "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" ]] \
        || { echo "FR13 fixed32 batched BV8 production requires a qualified fixed32 mode" >&2; exit 2; }
    else
      [[ "${FR13_FIXED32_MODE:-}" == "tail6_fixed32" ]] \
        || { echo "FR13 fixed32 batched BV64 production requires tail6_fixed32" >&2; exit 2; }
    fi
    [[ "${ENFORCE_EAGER:-0}" == "0" \
       && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" ]] \
      || { echo "FR13 fixed32 batched B4 GDN production requires the FULL graph runtime" >&2; exit 2; }
    if [[ "$_fr13_batch_gdn_bv_production" == "8" ]]; then
      [[ "${FR10_METRICS:-0}" == "1" ]] \
        || { echo "FR13 fixed32 batched BV8 production requires FR10_METRICS=1" >&2; exit 2; }
      [[ -f "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
         && ! -L "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
         && -f "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" \
         && ! -L "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" ]] \
        || { echo "FR13 fixed32 batched BV8 production requires the pinned gate runtime closure" >&2; exit 2; }
    fi
    [[ -f "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
       && ! -L "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
       && "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" =~ ^[0-9a-f]{64}$ \
       && -f "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
       && ! -L "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
       && "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" =~ ^[0-9a-f]{64}$ ]] \
      || { echo "FR13 fixed32 batched B4 GDN production requires a pinned completed exact4 graph gate" >&2; exit 2; }
    rm -f "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json"
    if [[ "$_fr13_batch_gdn_bv_production" == "8" ]]; then
      python3 scripts/fr13_b4_gdn_bv8_pass.py install \
        --live-result "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
        --expected-live-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" \
        --gate-verdict "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
        --expected-gate-verdict-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" \
        --kernel-source src/lumo_flywheel_serving/fr10_gdn_tree_kernel.py \
        --runtime-manifest "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
        --gate-runner "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" \
        --out "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" \
        || { echo "FR13 fixed32 batched BV8 graph PASS attestation failed" >&2; exit 2; }
    else
      python3 scripts/fr13_b4_gdn_bv64_pass.py install \
        --live-result "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
        --expected-live-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" \
        --gate-verdict "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
        --expected-gate-verdict-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" \
        --kernel-source src/lumo_flywheel_serving/fr10_gdn_tree_kernel.py \
        --out "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" \
        || { echo "FR13 fixed32 BV64 graph PASS attestation failed" >&2; exit 2; }
    fi
    printf '%s\n' "$_fr13_batch_gdn_bv_production" \
      > "$LOG_DIR/fr13_fixed32_batch_gdn_bv_production.flag"
    chmod 400 "$LOG_DIR/fr13_fixed32_batch_gdn_bv_production.flag"
  else
    [[ -z "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" \
       && -z "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
       && -z "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" \
       && -z "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
       && -z "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" ]] \
      || { echo "FR13 graph PASS inputs are exact B4 production only" >&2; exit 2; }
    [[ -f "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" \
       && ! -L "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" ]] \
      || { echo "FR13_FIXED32_BATCH_GDN_PRODUCTION requires a regular live-gate PASS record" >&2; exit 2; }
  fi
  echo "1" > "$LOG_DIR/fr13_fixed32_batch_gdn_production.arm"
else
  rm -f "$LOG_DIR/fr13_fixed32_batch_gdn_production.arm" 2>/dev/null || true
fi
# FR13_SUBTREE_PARALLEL sidecars. EngineCore receives a curated environment
# that drops these FR13_* gates, so env-only reads silently select the
# monolithic scan. The worker-visible /logs arms are the serving authority;
# env reads remain supported by the kernel for offline/eager use.
_fr13_subtree_parallel="${FR13_SUBTREE_PARALLEL:-1}"
_fr13_subtree_selfcheck="${FR13_SUBTREE_PARALLEL_SELFCHECK:-0}"
case "$_fr13_subtree_parallel" in
  0|1) ;;
  *) echo "FR13_SUBTREE_PARALLEL must be 0 or 1" >&2; exit 2 ;;
esac
case "$_fr13_subtree_selfcheck" in
  0|1) ;;
  *) echo "FR13_SUBTREE_PARALLEL_SELFCHECK must be 0 or 1" >&2; exit 2 ;;
esac
if [[ "$_fr13_subtree_selfcheck" == "1" && "$_fr13_subtree_parallel" != "1" ]]; then
  echo "FR13_SUBTREE_PARALLEL_SELFCHECK=1 requires FR13_SUBTREE_PARALLEL=1" >&2
  exit 2
fi
# FR13_MAMBA_SPEC_BLOCKS_CDIV (default 1=ON, PATCH-TIME): the B4 mamba page
# lever. ONE flag, TWO coupled patch sites. (1) rewrites MambaSpec's
# num_speculative_blocks from num_speculative_tokens (31) to
# cdiv(num_speculative_tokens, mamba_block_size) (=1 at 31/1024), so the align
# allocator reserves 2 physical mamba pages per group per request instead of 32
# -- 6/request instead of 96 across the 3 GDN groups. (2) rewrites both gdn_attn
# spec-window sites to republish the single align spare page across logical
# columns 1..num_spec, so NO consumer is narrowed: the window stays num_spec+1
# wide over those 2 pages. Read only by fr10_phase4_patch_vllm_tree_gdn.py
# inside the container, so the -e line below is what actually carries it. The
# patcher enforces a 2-slot floor (col0 + one real scratch page) and fails loud
# if only one of the two halves applies -- see fr13_required_tree_flags.sh for
# the per-node consumer audit and the superseded verdict.
# The fallback below must track fr13_canonical_env.sh, which is the single
# source of truth for what this branch ships (PROMOTED ON 2026-08-10, 749f83af6).
# In practice every campaign path sources that file first, so this fallback is
# not reached -- but when it IS reached it must not contradict the shipped
# default, or a campaign would serve narrowing OFF while its provenance claimed
# ON. tests/test_fr13_mamba_spec_blocks_cdiv.py parses both files and compares.
case "${FR13_MAMBA_SPEC_BLOCKS_CDIV:-1}" in
  0|1) ;;
  *) echo "FR13_MAMBA_SPEC_BLOCKS_CDIV must be 0 or 1" >&2; exit 2 ;;
esac
# FR13 host-residual rung (all default 0=OFF, all PATCH-TIME, all fixed32-only).
# NVTX adds post-DFWD tail sub-ranges for the offline nsys reduction; DEFER
# moves the fixed32 census seal onto a retire thread; PREP_BAKE replaces the
# per-step tree depth-position derivation with the literals it can only
# produce under fixed32. Read only by fr10_phase4_patch_vllm_tree_gdn.py inside
# the container, so the -e lines below are what actually carry them; the
# patcher's main() preflight refuses any of them without FR13_FIXED32_MODE.
for _fr13_host_tail_flag in FR13_HOST_TAIL_NVTX FR13_HOST_TAIL_DEFER \
                            FR13_HOST_TAIL_PREP_BAKE; do
  case "${!_fr13_host_tail_flag:-0}" in
    0|1) ;;
    *) echo "$_fr13_host_tail_flag must be 0 or 1" >&2; exit 2 ;;
  esac
done
unset _fr13_host_tail_flag
# FR14 host rung: the two measurement flags, both default 0=OFF, both
# byte-identical when off (host_dfwd_characterization.md §3, §5.2).
#   FR13_DFWD_SPLIT     -- the 3-way drafter split (model / head / other). The
#     patcher's main() reads it at container pid 1 and writes
#     /logs/fr13_dfwd_split.flag, which the EngineCore worker reads (the curated
#     worker env drops bare FR13_* masters). It was NEVER forwarded here, only
#     the unrelated FR13_DFWD_SPLIT_NEEDLE was, so the flag file read "0" in
#     35/35 runroots and the timer never once engaged -- an unsatisfiable
#     measurement precondition, the same class as fr13.fixed32.sched_next.
#   FR13_LFWD_GPU_TIMER -- the verifier-head span around compute_logits, which
#     sits outside sfwd/dfwd/cfwd and whose cost has therefore been landing in
#     the reducer's overhead_other and being read as host overhead.
# FR13_DFWD_SPLIT_JSON is forwarded with a NON-EMPTY default below, on
# purpose: _Fr13DfwdSplit.dump() does os.environ.get(
# "FR13_DFWD_SPLIT_JSON", "/logs/fr13_dfwd_split.json"), and
# os.environ.get returns "" for a var that is SET-but-empty, so a ":-"
# default here would clobber the code default and drop the sidecar into
# ".<pid>" in the cwd instead of the bind-mounted /logs.
for _fr13_instrument_flag in FR13_DFWD_SPLIT FR13_LFWD_GPU_TIMER; do
  case "${!_fr13_instrument_flag:-0}" in
    0|1) ;;
    *) echo "$_fr13_instrument_flag must be 0 or 1" >&2; exit 2 ;;
  esac
done
unset _fr13_instrument_flag
if [[ ( "$_fr13_batch_gdn_byte_ab" == "1" \
        || "$_fr13_batch_gdn_graph_byte_ab" == "1" \
        || "$_fr13_batch_gdn_production" == "1" ) \
      && "$_fr13_subtree_parallel" != "1" ]]; then
  echo "FR13 fixed32 batched GDN requires FR13_SUBTREE_PARALLEL=1" >&2
  exit 2
fi
if [[ ( "$_fr13_batch_gdn_byte_ab" == "1" \
        || "$_fr13_batch_gdn_graph_byte_ab" == "1" \
        || "$_fr13_batch_gdn_production" == "1" ) \
      && "$_fr13_subtree_selfcheck" == "1" ]]; then
  echo "FR13 fixed32 batched GDN is incompatible with FR13_SUBTREE_PARALLEL_SELFCHECK=1" >&2
  exit 2
fi
if [[ "$_fr13_subtree_selfcheck" == "1" && "${ENFORCE_EAGER:-0}" != "1" ]]; then
  echo "FR13_SUBTREE_PARALLEL_SELFCHECK=1 requires ENFORCE_EAGER=1" >&2
  exit 2
fi
if [[ "$_fr13_subtree_parallel" == "1" ]]; then
  : > "$LOG_DIR/fr13_subtree_parallel.arm"
else
  rm -f "$LOG_DIR/fr13_subtree_parallel.arm" 2>/dev/null || true
fi
if [[ "$_fr13_subtree_selfcheck" == "1" ]]; then
  : > "$LOG_DIR/fr13_subtree_parallel_selfcheck.arm"
else
  rm -f "$LOG_DIR/fr13_subtree_parallel_selfcheck.arm" 2>/dev/null || true
fi
# FR13_COMMIT_ARGMAX_GATE sidecar (same worker-env-drop workaround): the worker curation drops the flag
# (keeps only *_DUMP). The patched rejection_sampler reads this sidecar OR the (dropped) env.
if [[ "${FR13_COMMIT_ARGMAX_GATE:-0}" == "1" ]]; then
  : > "$LOG_DIR/fr13_commit_argmax_gate.arm"
else
  rm -f "$LOG_DIR/fr13_commit_argmax_gate.arm" 2>/dev/null || true
fi
# FR13_DEVICE_MULTIDRAFT off-sidecar (worker-env-drop-proof): DEVICE_MULTIDRAFT defaults ON and is dropped
# from the worker env, so FR13_DEVICE_MULTIDRAFT=0 can't turn it off via env. This sidecar forces the
# Python committer loop (needed for the CAG gate; also a decisive device-vs-Python garble A/B).
if [[ "${FR13_DEVICE_MULTIDRAFT:-1}" == "0" ]]; then
  : > "$LOG_DIR/fr13_device_multidraft_off.arm"
else
  rm -f "$LOG_DIR/fr13_device_multidraft_off.arm" 2>/dev/null || true
fi
# FR13_DRAFT_SOURCE=merged sidecar (same worker-env-drop workaround): the worker drops FR13_* env, so
# the MTP-k+Arctic-suffix merged drafter seam (fr10_phase4_patch_vllm_tree_gdn.py) reads THIS sidecar
# to enable merged mode. Default (absent/mtp) => byte-identical locked cat9 drafter, zero arctic.
if [[ "${FR13_DRAFT_SOURCE:-mtp}" == "merged" ]]; then
  : > "$LOG_DIR/fr13_draft_source_merged.arm"
else
  rm -f "$LOG_DIR/fr13_draft_source_merged.arm" 2>/dev/null || true
fi
# accept>5 TAIL mode sidecar (same worker-env-drop workaround): caps native MTP forwards at the head
# (head_depth-1) + appends the deep Arctic chain (depths head_depth..wide_D-1). REQUIRES the merged
# sidecar too (the Arctic cache lifecycle rides on the merged runner hook). Absent => no tail.
if [[ "${FR13_TAIL_MODE:-0}" == "1" ]]; then
  : > "$LOG_DIR/fr13_tail_mode.arm"
  echo "[launch] TAIL mode ON -> /logs/fr13_tail_mode.arm (head_depth=5 + arctic chain to wide_D)"
else
  rm -f "$LOG_DIR/fr13_tail_mode.arm" 2>/dev/null || true
fi
# HYDRA23 exact-shape sidecar. The worker strips FR13_* variables, while the
# patched drafter must fail loud if its full-path Arctic columns are paired
# with any other tree.
if [[ "${FR13_HYDRA23:-0}" == "1" ]]; then
  : > "$LOG_DIR/fr13_hydra23.arm"
  echo "[launch] HYDRA23 ON -> /logs/fr13_hydra23.arm (root-rank1 rescue chain length 4)"
else
  rm -f "$LOG_DIR/fr13_hydra23.arm" 2>/dev/null || true
fi
# Direction-2 d6-branch: bridge FR13_TAIL_BRANCHES/DEPTHS past the worker env-strip via a /logs sidecar
# (value-carrying, like the prewarm corpus). decide_tail reads "<branches> <depths>". Absent => spine-only.
if [[ -n "${FR13_TAIL_BRANCHES:-}" && "${FR13_TAIL_BRANCHES:-0}" != "0" ]]; then
  echo "${FR13_TAIL_BRANCHES} ${FR13_TAIL_BRANCH_DEPTHS:-0}" > "$LOG_DIR/fr13_tail_branches.cfg"
  echo "[launch] TAIL branches ON -> /logs/fr13_tail_branches.cfg (${FR13_TAIL_BRANCHES} branches x ${FR13_TAIL_BRANCH_DEPTHS:-0} depths)"
else
  rm -f "$LOG_DIR/fr13_tail_branches.cfg" 2>/dev/null || true
fi
# FR14 lever 2: suffix-aware MTP pass gating sidecar (same worker-env-drop
# workaround, value-carrying like fr13_tail_branches.cfg above). When armed, the
# drafter may run TWO post-root MTP forwards instead of four on steps whose
# committed context has a strong suffix recurrence, and Arctic fills draft
# positions 3..10 instead of 5..10. The four depth-4/5 runner-up columns are
# duplicate-sibling padded; the mask, the 31-column pack and the verify rows are
# unchanged, so a gated step is a fill-source change, not a shape change.
# This is ACCEPTANCE-AFFECTING on the steps it fires, so: default OFF, a typo is
# fatal rather than a silent arm/disarm, and it refuses to arm without the tail
# seam it hands off to. Predicate, pre-registration and offline evidence:
# results/fr14_nvfp4_port_20260816/suffix_pass_gating.md
# TAIL10 / hydra31_fixed32 (stage 2). The mode reaches the worker through the
# /logs sidecar the launcher already writes; nothing extra is forwarded. What is
# added here is refusal: several levers were QUALIFIED ON HYDRA27's physical
# tree, and hydra31 is a different tree (ids >= 17 carry different paths, both
# topology digests differ). Combining them would present a hydra27 credential
# for a tree it never saw. Refused at launch rather than discovered on a boot --
# the same discipline the suffix-gate incompatibilities use.
case "${FR13_FIXED32_MODE:-}" in
  ""|tail6_fixed32|hydra27_fixed32|hydra31_fixed32) ;;
  *) echo "FR13_FIXED32_MODE must be empty, tail6_fixed32, hydra27_fixed32 or hydra31_fixed32" >&2; exit 2 ;;
esac
if [[ "${FR13_FIXED32_MODE:-}" == "hydra31_fixed32" ]]; then
  for _fr14_h31_incompat in \
    FR13_CFWD_PACKED_WALK_NODE_TRUST_BYTE_AB \
    FR13_CFWD_PACKED_WALK_NODE_TRUST_PRODUCTION \
    FR13_CFWD_PACKED_WALK_ACTIVE_DEPTH_BYTE_AB \
    FR13_CFWD_LOGIT_DIRECT_BYTE_AB \
    FR13_CFWD_LOGIT_DIRECT_PRODUCTION \
    FR13_DRAFT_HEAD_FP8 \
    FR13_DRAFT_HEAD_M32_LIVE_AB \
    FR13_DRAFT_HEAD_M32_PRODUCTION \
    FR13_DRAFT_HEAD_M1_R64_U8_LIVE_AB \
    FR13_DRAFT_HEAD_M1_R64_U8_PRODUCTION \
    FR13_DRAFT_HEAD_M4_R64_U8_LIVE_AB \
    FR13_DRAFT_HEAD_M4_R64_U8_PRODUCTION; do
    if [[ "${!_fr14_h31_incompat:-0}" != "0" ]]; then
      echo "FR13_FIXED32_MODE=hydra31_fixed32 is incompatible with $_fr14_h31_incompat (qualified on the hydra27 tree)" >&2
      exit 2
    fi
  done
  unset _fr14_h31_incompat
  echo "[launch] TAIL10 profile hydra31_fixed32 (31 armed drafts, Arctic tail 10, walk cap 16)"
fi
# FR14 lane 1: fused draft top-k (FR14_FUSED_DRAFT_TOPK).
# PROMOTED 2026-08-18 by Mark's ruling (pass 57): live byte-proof 268 paths /
# 0 diffs / 96 215 steps, -0.071 ms bracket, accept flat, eyeball clean. Evidence
# and kernel contract: results/fr14_nvfp4_port_20260816/fused_draft_topk.md.
# Default is now ON, and the .so + its sha256 default to the promoted artifact so
# a plain launch actually serves the promoted kernel.
# NOTHING RELAXES. A promoted default that silently fell back to the unfused path
# on a missing binary would be a silent no-op, so a missing, symlinked or
# mismatched .so is a REFUSAL. Explicit FR14_FUSED_DRAFT_TOPK=0 remains the
# opt-out the paired A/Bs need.
# The proposer reads os.environ directly and that path is proven live
# (FR13_DRAFTER_GRAPH=1 in container_env.txt with graph_replays=1 in the same
# steps' census), so -e forwarding is the right mechanism -- no sidecar needed.
_fr14_fused_topk_so_default=/workspace/output/fr14_fused_draft_topk_build/fr14_dfwd_full_topk_sm121a.abi3.so
_fr14_fused_topk_sha_default=8f7a99e78c0898a4221f045aa8e15a8085883dbc41b08f609da0da71e66a449e
case "${FR14_FUSED_DRAFT_TOPK:-1}" in
  0|1) ;;
  *) echo "FR14_FUSED_DRAFT_TOPK must be exactly 0 or 1" >&2; exit 2 ;;
esac
case "${FR14_FUSED_DRAFT_TOPK_BLOCKS:-64}" in
  ''|*[!0-9]*) echo "FR14_FUSED_DRAFT_TOPK_BLOCKS must be an integer in 1..121" >&2; exit 2 ;;
esac
if (( ${FR14_FUSED_DRAFT_TOPK_BLOCKS:-64} < 1 || ${FR14_FUSED_DRAFT_TOPK_BLOCKS:-64} > 121 )); then
  echo "FR14_FUSED_DRAFT_TOPK_BLOCKS must be an integer in 1..121" >&2
  exit 2
fi
if [[ "${FR14_FUSED_DRAFT_TOPK:-1}" == "1" ]]; then
  _fr14_fused_topk_sha=${FR14_FUSED_DRAFT_TOPK_SHA256:-$_fr14_fused_topk_sha_default}
  _fr14_fused_topk_so=${FR14_FUSED_DRAFT_TOPK_SO:-$_fr14_fused_topk_so_default}
  if [[ ! "$_fr14_fused_topk_sha" =~ ^[0-9a-f]{64}$ ]]; then
    echo "FR14_FUSED_DRAFT_TOPK=1 requires FR14_FUSED_DRAFT_TOPK_SHA256 (64 lowercase hex)" >&2
    exit 2
  fi
  if [[ -z "$_fr14_fused_topk_so" ]]; then
    echo "FR14_FUSED_DRAFT_TOPK=1 requires FR14_FUSED_DRAFT_TOPK_SO" >&2
    exit 2
  fi
  # Prove the artifact HOST-side, before the container starts. The patcher
  # re-hashes it inside the container too; this makes the failure a launch
  # refusal with a readable message instead of an engine death mid-boot.
  _fr14_fused_topk_host=$_fr14_fused_topk_so
  if [[ "$_fr14_fused_topk_host" == /workspace/* ]]; then
    _fr14_fused_topk_host="$REPO/${_fr14_fused_topk_host#/workspace/}"
  fi
  if [[ ! -f "$_fr14_fused_topk_host" || -L "$_fr14_fused_topk_host" ]]; then
    echo "FR14_FUSED_DRAFT_TOPK is PROMOTED-ON but its pinned .so is missing: $_fr14_fused_topk_host" >&2
    echo "  the artifact lives under output/ (gitignored), so a fresh tree must rebuild it:" >&2
    echo "    python3 scripts/fr14_build_dfwd_full_topk.py" >&2
    echo "  or set FR14_FUSED_DRAFT_TOPK=0 to opt out. Refusing rather than silently" >&2
    echo "  serving the unfused path." >&2
    exit 2
  fi
  if [[ "$(sha256sum "$_fr14_fused_topk_host" | cut -d' ' -f1)" != "$_fr14_fused_topk_sha" ]]; then
    echo "FR14_FUSED_DRAFT_TOPK pinned .so sha256 mismatch: $_fr14_fused_topk_host" >&2
    exit 2
  fi
  echo "[launch] FUSED DRAFT TOP-K ON (promoted default; blocks=${FR14_FUSED_DRAFT_TOPK_BLOCKS:-64} so=$_fr14_fused_topk_so)"
else
  echo "[launch] FUSED DRAFT TOP-K OFF (explicit opt-out of the promoted default)"
fi
case "${FR14_SUFFIX_PASS_GATE:-0}" in
  0|1) ;;
  *) echo "FR14_SUFFIX_PASS_GATE must be 0 or 1" >&2; exit 2 ;;
esac
if [[ "${FR14_SUFFIX_PASS_GATE:-0}" == "1" ]]; then
  if [[ "${FR13_TAIL_MODE:-0}" != "1" || "${FR13_DRAFT_SOURCE:-mtp}" != "merged" ]]; then
    echo "FR14_SUFFIX_PASS_GATE=1 requires FR13_TAIL_MODE=1 and FR13_DRAFT_SOURCE=merged" >&2
    exit 2
  fi
  if [[ -n "${FR13_TAIL_BRANCHES:-}" && "${FR13_TAIL_BRANCHES:-0}" != "0" ]]; then
    echo "FR14_SUFFIX_PASS_GATE=1 is incompatible with FR13_TAIL_BRANCHES" >&2
    exit 2
  fi
  # FR14 lever 2 x draft-head production levers: the split capture re-issues the
  # drafter graph manifest signature, and the M32/U8/FP8 head attestations bind a
  # HARDCODED signature literal for the single 4-pass graph. Arming both would
  # present a half-graph to a credential minted for a whole one. The BM8
  # production attestation is a second case: it is scoped begin/end per capture,
  # and a split capture opens two. Refused here rather than discovered on a boot
  # -- which is exactly how Arm G was found (suffix_pass_gating.md 11).
  for _fr14_gate_incompat in \
    FR13_DRAFT_HEAD_M32_PRODUCTION \
    FR13_DRAFT_HEAD_M1_R64_U8_PRODUCTION \
    FR13_DRAFT_HEAD_M4_R64_U8_PRODUCTION \
    FR13_DRAFT_HEAD_FP8 \
    FR13_DFWD_UNIFIED_BM8_PRODUCTION \
    FR13_DFWD_UNIFIED_BM8_LIVE_AB \
    FR13_DRAFT_HEAD_M32_LIVE_AB \
    FR13_DRAFT_HEAD_M1_R64_U8_LIVE_AB \
    FR13_DRAFT_HEAD_M4_R64_U8_LIVE_AB; do
    if [[ "${!_fr14_gate_incompat:-0}" != "0" ]]; then
      echo "FR14_SUFFIX_PASS_GATE=1 is incompatible with $_fr14_gate_incompat (drafter graph credential is per-capture)" >&2
      exit 2
    fi
  done
  unset _fr14_gate_incompat
  if ! grep -q "FR14_GATE_SPLIT_GRAPH" "$REPO/scripts/fr10_phase4_patch_vllm_tree_gdn.py"; then
    echo "FR14_SUFFIX_PASS_GATE=1 refused: the drafter split-graph half is NOT landed." >&2
    echo "  The gate would hand decide_fixed32 a 3-depth MTP head while the drafter" >&2
    echo "  still runs all four post-root forwards -- a malformed tree at the verifier." >&2
    echo "  The interlock clears itself when the split lands (sentinel FR14_GATE_SPLIT_GRAPH)." >&2
    echo "  see results/fr14_nvfp4_port_20260816/suffix_pass_gating.md" >&2
    exit 2
  fi
  echo "${FR14_SUFFIX_PASS_GATE_NGRAM:-8} ${FR14_SUFFIX_PASS_GATE_MIN_AGREE:-0.75} ${FR14_SUFFIX_PASS_GATE_MIN_HISTORY:-256}" > "$LOG_DIR/fr14_suffix_pass_gate.cfg"
  echo "[launch] SUFFIX PASS GATE ON -> /logs/fr14_suffix_pass_gate.cfg (ngram=${FR14_SUFFIX_PASS_GATE_NGRAM:-8} min_agree=${FR14_SUFFIX_PASS_GATE_MIN_AGREE:-0.75} min_history=${FR14_SUFFIX_PASS_GATE_MIN_HISTORY:-256})"
else
  rm -f "$LOG_DIR/fr14_suffix_pass_gate.cfg" 2>/dev/null || true
fi
# PRE-WARM corpus sidecar (design §6b): worker drops FR13_* env, so copy the host corpus into /logs (mounted)
# and maybe_prewarm() reads the fixed /logs/fr13_prewarm_corpus.jsonl. Absent => cold trie (never-regress).
if [[ -n "${FR13_PREWARM_TRIE:-}" && -f "${FR13_PREWARM_TRIE}" ]]; then
  cp "$FR13_PREWARM_TRIE" "$LOG_DIR/fr13_prewarm_corpus.jsonl" && echo "[launch] pre-warm corpus -> /logs ($(wc -l < "$FR13_PREWARM_TRIE") seqs)"
else
  rm -f "$LOG_DIR/fr13_prewarm_corpus.jsonl" 2>/dev/null || true
fi
if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  _fixed32_same_name_containers=$(
    docker ps -aq --filter "name=^/${CONTAINER}$"
  ) || {
    echo "unable to enumerate the exact fixed32 container name" >&2
    exit 2
  }
  if [[ -n "$_fixed32_same_name_containers" ]]; then
    echo "fixed32 exact container name already exists: $CONTAINER" >&2
    exit 2
  fi
  unset _fixed32_same_name_containers
else
  docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
fi

set -a
if (( _FR13_LOCAL_ENV_SOURCED == 0 )) && [[ -f "$REPO/.lumo.local.env" ]]; then
  source "$REPO/.lumo.local.env"
fi
set +a
if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  [[ "${VLLM_DISABLE_REQUEST_ID_RANDOMIZATION:-1}" == "1" ]] \
    || {
      echo "fixed32 request-ID binding changed after local environment loading" >&2
      exit 2
    }
  VLLM_DISABLE_REQUEST_ID_RANDOMIZATION=1
  export VLLM_DISABLE_REQUEST_ID_RANDOMIZATION
fi

_lumo_truthy() {
  case "${1,,}" in
    1|true|yes|on) return 0 ;;
    *) return 1 ;;
  esac
}

LUMO_NSYS_WRAP_VLLM=${LUMO_NSYS_WRAP_VLLM:-0}
LUMO_NSYS_BIN=${LUMO_NSYS_BIN:-/opt/nvidia/nsight-systems-cli/2026.2.1/bin/nsys}
LUMO_NSYS_DELAY_S=${LUMO_NSYS_DELAY_S:-600}
LUMO_NSYS_DURATION_S=${LUMO_NSYS_DURATION_S:-150}
# DEFAULT-OFF deferred collection. When 1, the wrapped session is created with
# --start-later=true and collects NOTHING until an external `nsys start
# --session=<name>` arrives; --delay/--duration are then not passed at all
# (nsys documents --start-later as overriding --delay, and a --duration paired
# with a deferred start would re-impose a WALL bound on a step-gated capture).
#
# WHY THIS EXISTS: wall-time gating cannot address a forward-step window. The
# B4 width-4 operating point is defined in ABSOLUTE forward-step indices, and
# the admit->first-step hydration lag is ~118 steps (~43 s), so any fixed
# --delay drifts off the window it claims to profile. With this flag the gate
# is an external poller on vllm:fr13_decode_forward_gpu_steps_total -- the same
# counter that indexes the work census.
#
# 0 reproduces the pre-existing delay/duration prefix byte-for-byte, so the
# citable B1 attribution path is unchanged.
LUMO_NSYS_START_LATER=${LUMO_NSYS_START_LATER:-0}
# Periodic CUPTI buffer flush (ms). Without it, per-kernel records (incl. graph
# node-level kernels) are dropped as "incomplete" at the delayed-duration session
# stop on GB10 (fr13_b1_profile_bind: 55k/78k events dropped, zero kernel rows).
LUMO_NSYS_FLUSH_MS=${LUMO_NSYS_FLUSH_MS:-100}
# Semicolon-separated lines appended to the in-container nsys user config
# ("$nsys -z"). Default works around the GB10 drop class where ALL per-kernel
# rows are "incomplete CUPTI events dropped ... GPU timestamp information have
# not been retrieved" even with periodic flushes (NVIDIA-documented
# CuptiUseRawGpuTimestamps=false workaround; fr13_b1_profile_node: 102,320
# dropped with --cuda-flush-interval 100 and zero kernel tables).
LUMO_NSYS_CONFIG_DIRECTIVES=${LUMO_NSYS_CONFIG_DIRECTIVES:-CuptiUseRawGpuTimestamps=false}
# nsys --trace value. On GB10 + CUDA 13 the default 'cuda' engages the HARDWARE
# trace engine for kernel records; in delayed-duration sessions ALL kernel rows
# are then dropped ("GPU timestamp information have not been retrieved").
# 'cuda,cuda-sw' forces the software CUPTI kernel-record path (memcpy/memset/
# runtime rows always survived; only hw-trace kernel rows dropped).
LUMO_NSYS_TRACE=${LUMO_NSYS_TRACE:-cuda,nvtx}
LUMO_NSYS_OUTPUT=${LUMO_NSYS_OUTPUT:-/logs/nsys_vllm_${CONTAINER}}
NSYS_DOCKER_ARGS=()
if _lumo_truthy "$LUMO_NSYS_WRAP_VLLM"; then
  if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
    [[ "${LUMO_NSYS_SESSION_NAME:-}" =~ \
       ^fr13-fixed32-[0-9]{8}T[0-9]{6}Z-p[1-9][0-9]*$ ]] \
      || {
        echo "fixed32 attribution requires a pinned run-unique Nsight session name" >&2
        exit 2
      }
  fi
  for nsight_mount in /opt/nvidia /usr/local/cuda-13.0; do
    if [[ ! -e "$nsight_mount" ]]; then
      echo "LUMO_NSYS_WRAP_VLLM enabled but Nsight mount path is missing: $nsight_mount" >&2
      exit 2
    fi
    NSYS_DOCKER_ARGS+=(-v "$nsight_mount:$nsight_mount:ro")
  done
fi

# stale dcgm-sampler sweep (2026-07-24): gate-era sample_dcgm_during_task
# processes survive force-teardowns holding /dev/nvidia* and kill the NEXT
# boot pre-health (reference_dcgm_samplers_block_mem_recovery; observed 24h
# survivors). Sweep BEFORE memory recovery so the device is actually free.
pkill -f "sample_dcgm_during_task.py" 2>/dev/null && sleep 2 || true

PYTHONPATH="$REPO/src${PYTHONPATH:+:$PYTHONPATH}" python3 - <<'PY'
from lumo_flywheel_serving.model_server import recover_host_memory

recover_host_memory()
PY

# FR14 PAGE-CACHE DROP (2026-08-16). MemAvailable counts reclaimable page
# cache as "available", but the GB10 unified-memory allocator does not: the
# first NVFP4 boot attempt was REFUSED with 32 GiB free of a 117.5 GiB pool
# purely because 54 GB of checkpoint downloads were still sitting in page cache
# (results/fr14_nvfp4_port_20260816/REDTEAM_20260816.md pass 6, doctrine (i)).
# `sync` + drop_caches converts that cache back into genuinely free pages.
#
# `sudo -n` is SANCTIONED here and is deliberately non-interactive: this must
# never block an unattended campaign on a password prompt. If the sudoers rule
# is absent the drop is skipped (|| true) and the MemFree gate below still
# fires -- loudly, and before ~8 minutes of engine boot are spent.
sync
sudo -n sysctl vm.drop_caches=3 >/dev/null 2>&1 || true

free -h
GPU_UTIL="$GPU_UTIL" python3 - <<'PY'
import os
from pathlib import Path

fields = {}
for line in Path("/proc/meminfo").read_text().splitlines():
    key, value = line.split(":", 1)
    fields[key] = int(value.strip().split()[0])

available_gib = fields.get("MemAvailable", 0) / 1024 / 1024
swap_used_kib = fields.get("SwapTotal", 0) - fields.get("SwapFree", 0)
if available_gib < 80 or swap_used_kib != 0:
    raise SystemExit(
        "FR13 launch aborted: host memory recovery did not produce "
        f"MemAvailable>=80GiB and swap_used==0; "
        f"MemAvailable={available_gib:.2f}GiB "
        f"swap_used={swap_used_kib / 1024 / 1024:.2f}GiB"
    )

# FR14 unified-memory gate. On GB10 the "GPU" pool IS host RAM, so the engine's
# demand is gpu_memory_utilization x MemTotal and it is measured against
# genuinely FREE pages, not MemAvailable. Reproduce that arithmetic here so a
# doomed boot dies in one second instead of eight minutes.
total_gib = fields.get("MemTotal", 0) / 1024 / 1024
free_gib = fields.get("MemFree", 0) / 1024 / 1024
gpu_util = float(os.environ["GPU_UTIL"])
required_gib = gpu_util * total_gib
if free_gib < required_gib:
    raise SystemExit(
        "FR14 launch aborted: unified-memory preflight. The engine will "
        f"demand gpu_memory_utilization={gpu_util} x MemTotal={total_gib:.2f}"
        f"GiB = {required_gib:.2f}GiB, but only MemFree={free_gib:.2f}GiB is "
        "free (MemAvailable="
        f"{available_gib:.2f}GiB includes reclaimable page cache, which the "
        "unified-memory allocator will NOT reclaim for you). Free memory "
        "first: `sync && sudo sysctl vm.drop_caches=3`, stop other "
        "containers, or lower GPU_UTIL."
    )
print(
    f"[launch] unified-memory preflight OK: MemFree={free_gib:.2f}GiB >= "
    f"required={required_gib:.2f}GiB (GPU_UTIL={gpu_util}, "
    f"MemTotal={total_gib:.2f}GiB)"
)
PY

# FR13 §48 class-9 trap fix: auto-forward EVERY experiment flag set in this shell
# (FR<N>_*, LUMO_*, VLLM_*) into the container so a new flag can never be silently
# absent in-container (the patcher reads flags at patch time inside the container).
# Placed BEFORE the explicit -e list: docker takes the LAST occurrence of a name,
# so the explicit entries below keep their ${VAR:-default} semantics unchanged.
# FR13_TORCHPROF: arm vLLM's BUILT-IN torch profiler (with_stack defaults
# TRUE in-engine) via serve CLI config — engine config, not env, so the
# worker-env-drop class cannot touch it. Window control = POST /start_profile
# + /stop_profile (routes attach only when this config is set). DIAGNOSTIC
# ARM ONLY: in-window numbers carry capture overhead; label everything
# derived from it diagnostic-only, never compare as clean speed.
FR13_PROFILER_FLAGS=""
if [[ "${FR13_TORCHPROF:-0}" == "1" ]]; then
  FR13_PROFILER_FLAGS="--profiler-config.profiler=torch --profiler-config.torch_profiler_dir=/logs/torchprof"
fi

FR13_ENV_FORWARD_ARGS=()
while IFS= read -r _v; do
  [[ "$_v" == "FR13_FIXED32_INGRESS_SECRET_FILE" \
     || "$_v" == "FR13_FIXED32_MIDDLEWARE_FLAGS" \
     || "$_v" == "FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" \
     || "$_v" == "FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_SO" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_RESOURCE_CREDENTIAL" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_RESOURCE_CREDENTIAL_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_GDN_GQA_GROUP3_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_BATCH_GDN_BYTE_AB_REAL_EVENT_PATH" \
     || "$_v" == "FR13_FIXED32_CUTLASS_B4_BYTE_AB_REAL_EVENT_PATH" \
     || "$_v" == "FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH" \
     || "$_v" == "FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH" \
     || "$_v" == "FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH" \
     || "$_v" == "FR13_DFWD_K64_TOP3_SO" \
     || "$_v" == "FR13_DRAFT_HEAD_M1_R64_U8_SO" \
     || "$_v" == "FR13_DRAFT_HEAD_M4_R64_U8_SO" ]] && continue
  if [[ -n "${FR13_FIXED32_MODE:-}" \
     && "$_v" == "VLLM_DISABLE_REQUEST_ID_RANDOMIZATION" ]]; then
    continue
  fi
  case "$(declare -p "$_v" 2>/dev/null)" in declare\ -a*|declare\ -A*) continue;; esac
  [[ "${!_v}" == *$'\n'* ]] && continue
  FR13_ENV_FORWARD_ARGS+=( -e "${_v}=${!_v}" )
done < <(compgen -v | grep -E '^(FR[0-9]+_|LUMO_|VLLM_)' | sort)

if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  [[ -f "$FR13_FIXED32_INGRESS_SECRET_FILE" \
     && ! -L "$FR13_FIXED32_INGRESS_SECRET_FILE" \
     && "$(stat -c '%a' "$FR13_FIXED32_INGRESS_SECRET_FILE")" == "600" ]] \
    || {
      echo "fixed32 ingress secret changed before Docker mount/use" >&2
      exit 2
    }
fi

docker run -d --pull=never --name "$CONTAINER" --gpus all --ipc=host \
  --memory="$DOCKER_MEM_CAP" --memory-swap="$DOCKER_MEM_CAP" \
  --cap-add=SYS_PTRACE \
  --ulimit memlock=-1 --ulimit stack=67108864 -p "$PORT:9950" \
  -v "$REPO:/workspace" -v /models:/models -v "$LOG_DIR:/logs" \
  -v "$FORKED_FA2_SO:/tmp/fr13_fork_fa2.so:ro" \
  "${FR13_FP8_QUANT_REGCACHE_DOCKER_ARGS[@]}" \
  "${FR13_CUTLASS_WAVE_DOCKER_ARGS[@]}" \
  "${FR13_DFWD_K64_TOP3_DOCKER_ARGS[@]}" \
  "${FR13_DRAFT_HEAD_U8_DOCKER_ARGS[@]}" \
  "${FR13_DRAFT_HEAD_M4_U8_DOCKER_ARGS[@]}" \
  -v "${FR13_COMPILE_CACHE_DIR:-$HOME/.cache/fr13_vllm_container_cache}:/root/.cache" \
  "${NSYS_DOCKER_ARGS[@]}" \
  "${FR13_FIXED32_DOCKER_ARGS[@]}" \
  "${FR13_ENV_FORWARD_ARGS[@]}" \
  -e ENFORCE_EAGER="${ENFORCE_EAGER:-0}" \
  -e CUDAGRAPH_MODE="$CUDAGRAPH_MODE" \
  -e MAX_NUM_SEQS="$MAX_NUM_SEQS" \
  -e SWE_CONCURRENCY="${SWE_CONCURRENCY:-}" \
  -e FR13_FIXED32_MIDDLEWARE_FLAGS="$FR13_FIXED32_MIDDLEWARE_FLAGS" \
  -e PYTORCH_CUDA_ALLOC_CONF="$PYTORCH_CUDA_ALLOC_CONF" \
  -e VLLM_BATCH_INVARIANT="$BATCH_INVARIANT" \
  -e LUMO_BATCH_INVARIANT_VLLM="${LUMO_BATCH_INVARIANT_VLLM:-$BATCH_INVARIANT}" \
  -e LUMO_NSYS_WRAP_VLLM="$LUMO_NSYS_WRAP_VLLM" \
  -e LUMO_NSYS_BIN="$LUMO_NSYS_BIN" \
  -e LUMO_NSYS_DELAY_S="$LUMO_NSYS_DELAY_S" \
  -e LUMO_NSYS_DURATION_S="$LUMO_NSYS_DURATION_S" \
  -e LUMO_NSYS_START_LATER="$LUMO_NSYS_START_LATER" \
  -e LUMO_NSYS_FLUSH_MS="$LUMO_NSYS_FLUSH_MS" \
  -e LUMO_NSYS_CONFIG_DIRECTIVES="$LUMO_NSYS_CONFIG_DIRECTIVES" \
  -e LUMO_NSYS_TRACE="$LUMO_NSYS_TRACE" \
  -e LUMO_NSYS_OUTPUT="$LUMO_NSYS_OUTPUT" \
  -e FR13_BI_TREE_ATTN="$FR13_BI_TREE_ATTN" \
  -e ATTENTION_BACKEND="$ATTENTION_BACKEND" \
  -e FR13_TORCH_DET_WARN="${FR13_TORCH_DET_WARN:-0}" \
  -e FR13_TORCH_DET_WARN_LOG="${FR13_TORCH_DET_WARN_LOG:-/logs/fr13_torch_det_warn.log}" \
  -e FR13_TREE_PER_REQ_GEN="${FR13_TREE_PER_REQ_GEN:-1}" \
  -e FR13_TREE_REQKEY="${FR13_TREE_REQKEY:-1}" \
  -e FR13_TREE_REMAP_SEQ="${FR13_TREE_REMAP_SEQ:-1}" \
  -e FR13_TREE_BONUS_SELF="${FR13_TREE_BONUS_SELF:-1}" \
  -e FR13_CONV_COMMITTED_PATH="$FR13_CONV_COMMITTED_PATH" \
  -e FR13_APC_CONV_FIX="${FR13_APC_CONV_FIX:-1}" \
  -e FR13_APC_CONV_SNAPSHOT="${FR13_APC_CONV_SNAPSHOT:-0}" \
  -e FR13_APC_BLOCK_ALIGN_45477="${FR13_APC_BLOCK_ALIGN_45477:-1}" \
  -e FR13_SERVE_LOG="${FR13_SERVE_LOG:-0}" \
  -e FR13_LEAK_PROBE="${FR13_LEAK_PROBE:-0}" \
  -e FR13_FORCE_SPINE_COMMIT="$FR13_FORCE_SPINE_COMMIT" \
  -e FR13_DRAFTER_SINGLE_LOGITS="$FR13_DRAFTER_SINGLE_LOGITS" \
  -e FR13_EAGER_PACK="$FR13_EAGER_PACK" \
  -e FR13_TREE_CONV_FUSED="$FR13_TREE_CONV_FUSED" \
  -e FR13_FIX1_SELFCHECK="$FR13_FIX1_SELFCHECK" \
  -e FR13_FIX1_SELFCHECK_DUMP="$FR13_FIX1_SELFCHECK_DUMP" \
  -e FR13_COMMIT_ARGMAX_GATE="$FR13_COMMIT_ARGMAX_GATE" \
  -e FR13_COMMIT_ARGMAX_GATE_DUMP="$FR13_COMMIT_ARGMAX_GATE_DUMP" \
  -e FR13_FORK_MARGIN_DUMP="$FR13_FORK_MARGIN_DUMP" \
  -e FR13_FORK_MARGIN_DUMP_PATH="$FR13_FORK_MARGIN_DUMP_PATH" \
  -e FR13_REPLAY_ROUTE="${FR13_REPLAY_ROUTE:-1}" \
  -e FR13_REPLAY_BOUNDARY_LOG="${FR13_REPLAY_BOUNDARY_LOG:-0}" \
  -e FR13_REPLAY_BOUNDARY_LAYERS="${FR13_REPLAY_BOUNDARY_LAYERS:-layers.0.linear_attn}" \
  -e FR13_REPLAY_BOUNDARY_PATH="${FR13_REPLAY_BOUNDARY_PATH:-/logs/fr13_replay_boundary.jsonl}" \
  -e FR13_CHASE_DIAG="$FR13_CHASE_DIAG" \
