import importlib.util
import os
import subprocess
import sys

# FR13 merged drafter (MTP-k spine + Arctic suffix decoding). Fixed32 always
# reinstalls the exact hash-pinned source and fails closed on import/version
# drift. Legacy merged arms retain their historical best-effort behavior.
fixed32 = bool(os.environ.get('FR13_FIXED32_MODE'))
if fixed32:
    sys.path.insert(0, '/workspace/scripts')
    import fr13_fixed32_contract as contract

    print('[FR13-PRELAUNCH] installing hash-pinned Arctic for fixed32')
    subprocess.run([
        sys.executable, '-m', 'pip', 'install',
        '--disable-pip-version-check', '--force-reinstall', '--no-deps',
        contract.ARCTIC_PINNED_REQUIREMENT,
    ], check=True)
    from arctic_inference.suffix_decoding import SuffixDecodingCache
    import importlib.metadata

    version = importlib.metadata.version('arctic-inference')
    if version != contract.ARCTIC_VERSION:
        raise SystemExit(
            f'fixed32 Arctic version mismatch: {version} != {contract.ARCTIC_VERSION}'
        )
    print(
        '[FR13-PRELAUNCH] fixed32 Arctic pinned OK '
        f'version={version} cache={SuffixDecodingCache.__module__}.'
        f'{SuffixDecodingCache.__qualname__}'
    )
elif os.environ.get('FR13_DRAFT_SOURCE', 'mtp') != 'merged':
    print('[FR13-PRELAUNCH] FR13_DRAFT_SOURCE!=merged -- skipping arctic-inference install')
elif importlib.util.find_spec('arctic_inference') is None:
    print('[FR13-PRELAUNCH] installing arctic-inference for suffix decoding (merged drafter)')
    # NON-FATAL: a failed arctic build must NOT crash the boot -- the merged seam's get_cache()
    # returns None on import failure => pure-MTP fallback (never-regress). The ENGAGED gate then
    # reports VACUOUS and this log shows why.
    _rc = subprocess.call([
        sys.executable, '-m', 'pip', 'install',
        '--disable-pip-version-check', 'arctic-inference==0.1.2',
    ])
    if _rc == 0:
        print('[FR13-PRELAUNCH] arctic-inference installed OK')
    else:
        print('[FR13-PRELAUNCH] WARNING arctic-inference install FAILED rc=%d -> merged will fall back to pure MTP' % _rc)
else:
    print('[FR13-PRELAUNCH] arctic-inference already available')
PY
if [[ -n \"\${FR13_FIXED32_MODE:-}\" ]]; then
  python3 /workspace/scripts/fr13_fixed32_contract.py runtime-attestation \
    --output /logs/fr13_fixed32_runtime_attestation.json
fi
NSYS_PREFIX=()
case \"\${LUMO_NSYS_WRAP_VLLM,,}\" in
  1|true|yes|on)
    if [[ -n \"\${LUMO_NSYS_CONFIG_DIRECTIVES:-}\" ]]; then
      NSYS_CFG_PATH=\$(\"\$LUMO_NSYS_BIN\" -z)
      mkdir -p \"\$(dirname \"\$NSYS_CFG_PATH\")\"
      printf '%s\n' \"\$LUMO_NSYS_CONFIG_DIRECTIVES\" | tr ';' '\n' >> \"\$NSYS_CFG_PATH\"
      echo \"nsys config directives appended to \$NSYS_CFG_PATH:\"
      cat \"\$NSYS_CFG_PATH\"
    fi
    NSYS_PREFIX=(
      \"\$LUMO_NSYS_BIN\"
      profile
      \"--session-new=%q{LUMO_NSYS_SESSION_NAME}\"
    )
    case \"\${LUMO_NSYS_START_LATER,,}\" in
      1|true|yes|on)
        NSYS_PREFIX+=( --start-later=true )
        ;;
      *)
        NSYS_PREFIX+=(
          --delay \"\$LUMO_NSYS_DELAY_S\"
          --duration \"\$LUMO_NSYS_DURATION_S\"
        )
        ;;
    esac
    NSYS_PREFIX+=(
      --trace=\"\$LUMO_NSYS_TRACE\"
      --cuda-graph-trace=node
      --cuda-flush-interval \"\$LUMO_NSYS_FLUSH_MS\"
      --discard-environment=true
      --sample=none
      --cpuctxsw=none
      --force-overwrite=true
      -o \"\$LUMO_NSYS_OUTPUT\"
    )
    ;;
esac
exec \"\${NSYS_PREFIX[@]}\" vllm serve $SERVED_MODEL_PATH --served-model-name $SERVED_MODEL_NAME \
  --host 0.0.0.0 --port 9950 --max-num-seqs '$MAX_NUM_SEQS' \
  --gpu-memory-utilization '$GPU_UTIL' --max-model-len '$MAX_MODEL_LEN' --seed '${SEED:-0}' \
  $(if [[ -n "$KV_CACHE_MEMORY_BYTES" ]]; then printf '%s %s' '--kv-cache-memory-bytes' "$KV_CACHE_MEMORY_BYTES"; fi) \
  --attention-backend '$ATTENTION_BACKEND' --gdn-prefill-backend triton \
  --chat-template /workspace/docker/chat_templates/qwen3-openai-codex.jinja \
  --enable-auto-tool-choice --tool-call-parser qwen3_xml --reasoning-parser qwen3 \
  --speculative-config \"\$SPEC_CONFIG\" $APC_FLAGS $CG_FLAGS $KV_FP8_FLAGS $FR13_SERVE_BATCH_FLAGS $FR13_PROFILER_FLAGS \
  \$FR13_FIXED32_MIDDLEWARE_FLAGS \
  $(if [[ "${ENFORCE_EAGER:-0}" == "1" ]]; then printf '%s' '--enforce-eager'; fi)"

if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  [[ -f "$FR13_FIXED32_CIDFILE" && ! -L "$FR13_FIXED32_CIDFILE" ]] \
    || { echo "fixed32 Docker cidfile is missing or aliased" >&2; exit 2; }
  mapfile -t _fixed32_container_ids < "$FR13_FIXED32_CIDFILE"
  (( ${#_fixed32_container_ids[@]} == 1 )) \
    && [[ "${_fixed32_container_ids[0]}" =~ ^[0-9a-f]{64}$ ]] \
    || { echo "fixed32 Docker cidfile is malformed" >&2; exit 2; }
  _fixed32_container_id=${_fixed32_container_ids[0]}
  _fixed32_container_identity=$(
    docker inspect --format '{{.Id}} {{.Name}}' "$_fixed32_container_id"
  ) || { echo "fixed32 Docker cidfile identity is unavailable" >&2; exit 2; }
  read -r _fixed32_actual_id _fixed32_actual_name _fixed32_extra \
    <<< "$_fixed32_container_identity"
  [[ -z "$_fixed32_extra" ]] \
    && [[ "$_fixed32_actual_id" == "$_fixed32_container_id" ]] \
    && [[ "$_fixed32_actual_name" == "/$CONTAINER" ]] \
    || { echo "fixed32 Docker cidfile identity mismatch" >&2; exit 2; }
  FR13_FIXED32_CONTAINER_ID=$_fixed32_container_id
  echo "[launch] fixed32 container identity id=$_fixed32_container_id name=$CONTAINER"
  unset _fixed32_actual_id _fixed32_actual_name _fixed32_container_id
  unset _fixed32_container_identity _fixed32_container_ids _fixed32_extra
fi

# DURABLE OOM BACKSTOP: spawn the detached GPU/unified-mem guard for THIS container.
# It docker-kills the container if unified-avail nears the wall, converting an
# incipient GPU OOM (which would otherwise nuke the systemd --user session and take
# Claude down with it) into a relaunchable+loud container kill. Self-exits when the
# container is gone. Default-ON in the chokepoint so no caller can forget it.
if [[ "${GPU_OOM_GUARD:-1}" == "1" ]]; then
  if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
    GPU_GUARD_CONTAINER_ID="$FR13_FIXED32_CONTAINER_ID" \
    GPU_GUARD_EXPECTED_NAME="$CONTAINER" \
      setsid bash "$(dirname "$0")/gpu_oom_guard.sh" \
      >/dev/null 2>&1 </dev/null &
  else
    GPU_GUARD_NAME_GLOB="$CONTAINER" \
      setsid bash "$(dirname "$0")/gpu_oom_guard.sh" \
      >/dev/null 2>&1 </dev/null &
  fi
  disown 2>/dev/null || true
  echo "[launch] gpu_oom_guard armed for container=${FR13_FIXED32_CONTAINER_ID:-$CONTAINER} (floor=${GPU_GUARD_FLOOR_MIB:-9000}MiB)"
fi
